/* Tech 3D · Nivell 1 · unitat 6 «Del model a l'objecte» · guia del professor (m6-1 … m6-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren el
   model en 3D (TMEDIA.model): a la pissarra digital es pot girar amb el dit o amb el ratolí. Dades d'impressió FDM per a
   primària: filament de PLA d'1,75 mm, broquet d'uns 0,4 mm a uns 200 °C, capes d'uns 0,2 mm, voladissos fins a uns 45°. */
Object.assign(TGUIDE, (() => {
  const P = (id, t, s, p, c, o = {}) => ({ id, t, s, p, r: o.r || [0, 0, 0], c, ...o });
  const B = (id, t, s, x, y, z0, c, o = {}) => P(id, t, s, [x, y, z0 + s[2] / 2], c, o);
  const HB = (id, t, s, x, y, z0) => P(id, t, s, [x, y, z0 + s[2] / 2], '#9AA3B5', { hole: true });
  const FRANGES = { parts: Array.from({ length: 10 }, (_, i) => B('c' + i, 'box', [24, 24, 2], 0, 0, 2 * i, i % 2 ? '#B9A7FF' : '#7C5CFF')) };
  const REGLES = { parts: [B('r1', 'box', [20, 3, 100], -30, 0, 0, '#EC5FA8'), B('r2', 'box', [20, 100, 3], 25, 0, 0, '#2FB36D')] };
  const TORRE = { parts: [B('p1', 'box', [30, 30, 10], 0, 0, 0, '#3D7BF4'), B('p2', 'box', [22, 22, 10], 0, 0, 10, '#2FB36D'), B('p3', 'box', [14, 14, 10], 0, 0, 20, '#F7C531')] };
  const NE = '#1B2B6B', BL = '#F3F3EE';
  const PEO = c => ({ parts: [B('base', 'cyl', [22, 22, 4], 0, 0, 0, c), B('cos', 'cone', [16, 16, 20], 0, 0, 4, c), B('cap', 'sph', [12, 12, 12], 0, 0, 18, c)] });
  const PEO_COL = { parts: [B('base', 'cyl', [22, 22, 4], 0, 0, 0, '#E8453C'), B('cos', 'cone', [16, 16, 20], 0, 0, 4, '#F7C531'), B('cap', 'sph', [12, 12, 12], 0, 0, 18, '#3D7BF4')] };
  const REINA = z => ({ parts: [B('base', 'cyl', [24, 24, 4], 0, 0, 0, NE), B('cos', 'cone', [18, 18, 24], 0, 0, 4, NE, { top: 0.8 }), B('coll', 'cyl', [14, 14, 3], 0, 0, 28, NE), B('corona', 'tube', [14, 14, 6], 0, 0, z, '#F7C531', { w: 2 })] });
  const BOLET = { parts: [B('peu', 'cyl', [10, 10, 16], 0, 0, 0, BL), B('barret', 'cyl', [34, 34, 8], 0, 0, 16, '#E8453C')] };
  const XAPA = { parts: [B('a1', 'cyl', [40, 40, 5], 0, 0, 0, '#2FB36D')] };
  const MED50 = { parts: [B('a1', 'cyl', [50, 50, 3], 0, 0, 0, '#F5893A'), HB('f1', 'cyl', [5, 5, 20], 0, 19, 0)] };
  const BLK = B('bloc', 'box', [40, 28, 40], 0, 0, 0, '#3D7BF4');
  const POS6 = [[-12, -6], [0, -6], [12, -6], [-12, 6], [0, 6], [12, 6]];
  const SIX = POS6.map(([x, y], i) => HB('f' + (i + 1), 'cyl', [9, 9, 40], x, y, 2));
  const PORTA = { parts: [BLK, ...SIX] };
  const TALL = { parts: [BLK, ...SIX, P('tall', 'box', [50, 14, 50], [0, -13, 24], '#9AA3B5', { hole: true })] };
  const LLC = ['#E8453C', '#F7C531', '#2FB36D', '#3D7BF4', '#EC5FA8', '#FF8A3D'];
  const AMB_LLAPIS = { parts: [...PORTA.parts.map(p => ({ ...p, g: 'gb' })), ...POS6.flatMap(([x, y], i) => [B('l' + i, 'hex', [8, 6.93, 62], x, y, 2, LLC[i]), B('p' + i, 'cone', [7, 7, 9], x, y, 64, '#E8C39E')])] };
  return {
  /* ---------- Sessió 1 · Com treballa una impressora 3D ---------- */
  'm6-1': {
    obj: ["L'alumne/a explica com treballa una impressora 3D de filament: el plàstic es fon al broquet i es posa en línies, capa a capa, de baix a dalt.|El alumno/a explica cómo trabaja una impresora 3D de filamento: el plástico se funde en la boquilla y se pone en líneas, capa a capa, de abajo arriba.",
      "L'alumne/a calcula quantes capes té una peça a partir de la seva alçada (capes de 0,2 mm: 5 per mil·límetre).|El alumno/a calcula cuántas capas tiene una pieza a partir de su altura (capas de 0,2 mm: 5 por milímetro).",
      "L'alumne/a relaciona el temps d'impressió amb el nombre i la mida de les capes, i amb el gruix de capa.|El alumno/a relaciona el tiempo de impresión con el número y el tamaño de las capas, y con el grosor de capa.",
      "L'alumne/a tria com posar una peça a la placa per tenir menys capes i més estabilitat.|El alumno/a elige cómo poner una pieza en la placa para tener menos capas y más estabilidad."],
    comp: ['Tecnologia i digitalització: fabricació digital, funcionament d\'una impressora 3D i normes de seguretat|Tecnología y digitalización: fabricación digital, funcionamiento de una impresora 3D y normas de seguridad',
      'Matemàtiques, sentit de la mesura: mil·límetres i dècimes de mil·límetre; multiplicar per calcular capes|Matemáticas, sentido de la medida: milímetros y décimas de milímetro; multiplicar para calcular capas',
      "Matemàtiques, sentit espacial: posició i orientació d'un cos a l'espai (dret o estirat)|Matemáticas, sentido espacial: posición y orientación de un cuerpo en el espacio (de pie o tumbado)",
      'Pensament computacional: descompondre un objecte en capes que es fan una darrere l\'altra|Pensamiento computacional: descomponer un objeto en capas que se hacen una detrás de otra'],
    vocab: [['Filament|Filamento', "Fil de plàstic enrotllat en una bobina que fa servir la impressora.|Hilo de plástico enrollado en una bobina que usa la impresora."], ['Broquet|Boquilla', 'Punta calenta (uns 200 °C) per on surt el plàstic fos.|Punta caliente (unos 200 °C) por donde sale el plástico fundido.'],
      ['Capa|Capa', "Cada una de les làmines primes (uns 0,2 mm) que formen l'objecte.|Cada una de las láminas finas (unos 0,2 mm) que forman el objeto."], ['Capçal|Cabezal', 'La part de la impressora que porta el broquet i es mou en x i y.|La parte de la impresora que lleva la boquilla y se mueve en x e y.'],
      ['Placa d\'impressió|Placa de impresión', "La superfície plana on es comença a imprimir.|La superficie plana donde se empieza a imprimir."], ['PLA|PLA', 'El plàstic més habitual de les impressores de l\'escola, fet a partir de plantes.|El plástico más habitual de las impresoras de la escuela, hecho a partir de plantas.'],
      ['Gruix de capa|Grosor de capa', "Quant fa cada capa: com més fina, més llisa i més lenta.|Cuánto mide cada capa: cuanto más fina, más lisa y más lenta."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Com treballa una impressora 3D»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Cómo trabaja una impresora 3D»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Plastilina, una cartolina i un regle per parella; si en teniu, una peça impresa en 3D i una lupa|Plastilina, una cartulina y una regla por pareja; si tenéis, una pieza impresa en 3D y una lupa'],
      imprimir: ['Fitxa: comptem capes|Ficha: contamos capas'], prep: ["Preparar la plastilina en boles petites (una per parella) i una cartolina per fer de placa.|Preparar la plastilina en bolas pequeñas (una por pareja) y una cartulina para hacer de placa.", "Si teniu una impressora 3D, deixar-la a la vista (apagada) o fer un vídeo curt d'una impressió.|Si tenéis una impresora 3D, dejarla a la vista (apagada) o hacer un vídeo corto de una impresión.", 'Provar abans el repte del regle: cal posar Gir x = 90.|Probar antes el reto de la regla: hay que poner Giro x = 90.'] },
    plan: [
      { min: 5, t: 'La Nuvi rep visita|Nuvi recibe visita', fase: 'inici', fa: "Presenta la unitat i l'encàrrec: medalles de record per a la classe de 4t de l'Escola del Turó. Si teniu una peça impresa, feu-la passar amb una lupa: es veuen les ratlles de les capes.|Presenta la unidad y el encargo: medallas de recuerdo para la clase de 4.º de la Escuela del Turó. Si tenéis una pieza impresa, hacedla pasar con una lupa: se ven las rayas de las capas.",
        diu: ['Com creieu que es fa un objecte amb una impressora 3D?|¿Cómo creéis que se hace un objeto con una impresora 3D?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Filament, capes i temps|Filamento, capas y tiempo', fase: 'teoria', fa: "Explica el camí del filament fins al broquet i com la impressora fa una capa i puja. Calculeu junts les capes de la torre de franges (20 × 5 = 100). Parla del temps i del gruix de capa, i compara el regle dret i estirat girant-lo a la pissarra.|Explica el camino del filamento hasta la boquilla y cómo la impresora hace una capa y sube. Calculad juntos las capas de la torre de franjas (20 × 5 = 100). Habla del tiempo y del grosor de capa, y compara la regla de pie y tumbada girándola en la pizarra.",
        diu: ['Quantes capes té una peça d\'un centímetre?|¿Cuántas capas tiene una pieza de un centímetro?', 'Per què la Nuvi no pot començar per dalt?|¿Por qué Nuvi no puede empezar por arriba?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'Imprimeix amb plastilina|Imprime con plastilina', fase: 'desconnectat', fa: "Per parelles fan un «filament» de plastilina i construeixen un gotet de 6 capes sobre la cartolina. Mesuren l'alçada i calculen quant fa cada capa. Al final, proven de treure una capa cap enfora: preparen la idea de voladís de la sessió següent.|Por parejas hacen un «filamento» de plastilina y construyen un vasito de 6 capas sobre la cartulina. Miden la altura y calculan cuánto mide cada capa. Al final, prueban a sacar una capa hacia fuera: preparan la idea de voladizo de la sesión siguiente.",
        diu: ['Si cada capa vostra fa 5 mm, quantes capes de la Nuvi hi caben?|Si cada capa vuestra mide 5 mm, ¿cuántas capas de Nuvi caben?'], slides: ['s8'], app: 'Encara no: plastilina i regle.|Todavía no: plastilina y regla.', org: 'Per parelles|Por parejas' },
      { min: 22, t: 'Fitxes, torres i regles|Fichas, torres y reglas', fase: 'ordinador', fa: "Fan la sessió a l'app: compten capes, troben la peça que es fa l'última, fan la fitxa de 10 capes, la torre de tres pisos i estiren el regle. La medalla de 20 capes és un repte extra. Vigila que facin el càlcul abans d'escriure el número.|Hacen la sesión en la app: cuentan capas, encuentran la pieza que se hace la última, hacen la ficha de 10 capas, la torre de tres pisos y tumban la regla. La medalla de 20 capas es un reto extra. Vigila que hagan el cálculo antes de escribir el número.",
        diu: ['Quants mil·límetres són 10 capes?|¿Cuántos milímetros son 10 capas?', 'Mira el regle de costat: quantes capes té ara?|Mira la regla de lado: ¿cuántas capas tiene ahora?'], slides: ['s9', 's10', 's11'], app: 'Sessió «Com treballa una impressora 3D», fins a «La medalla del Taller».|Sesión «Cómo trabaja una impresora 3D», hasta «La medalla del Taller».', org: 'Individual|Individual' },
      { min: 8, t: 'La medalla del Taller|La medalla del Taller', fase: 'crea', fa: "Cada alumne/a dissenya la seva medalla: forma, color i un dibuix en relleu o gravat, amb un màxim de 20 capes (4 mm). Quan les comprovacions es marquen, la desen.|Cada alumno/a diseña su medalla: forma, color y un dibujo en relieve o grabado, con un máximo de 20 capas (4 mm). Cuando las comprobaciones se marcan, la guardan.",
        diu: ['Quantes capes té la teva medalla?|¿Cuántas capas tiene tu medalla?'], slides: ['s12'], app: 'Pas «La medalla del Taller».|Paso «La medalla del Taller».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa les tres idees clau (filament i broquet, capes de 0,2 mm, temps i orientació). Tiquet de sortida i proposta per a casa.|Repasa las tres ideas clave (filamento y boquilla, capas de 0,2 mm, tiempo y orientación). Ticket de salida y propuesta para casa.",
        diu: ['Expliqueu a un company com treballa la Nuvi en tres passos.|Explicad a un compañero cómo trabaja Nuvi en tres pasos.'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Confon capes i mil·límetres: diu que una peça de 10 mm té 10 capes.|Confunde capas y milímetros: dice que una pieza de 10 mm tiene 10 capas.", "Recordeu la regla: cada mil·límetre són 5 capes. Feu-ho amb els dits: 1 mm, 5 capes; 2 mm, 10 capes…|Recordad la regla: cada milímetro son 5 capas. Hacedlo con los dedos: 1 mm, 5 capas; 2 mm, 10 capas…"],
      ["Al repte del regle, gira en y o en z i el regle queda de cantell.|En el reto de la regla, gira en y o en z y la regla queda de canto.", "Que el miri de costat: ha de quedar pla, amb 3 mm d'alçada. Gir x = 90, o bé canviar les mides a 20, 100 i 3.|Que la mire de lado: tiene que quedar plana, con 3 mm de altura. Giro x = 90, o bien cambiar las medidas a 20, 100 y 3."],
      ["A la torre, posa els pisos nous a z = 0 i queden amagats dins del primer.|En la torre, pone los pisos nuevos en z = 0 y quedan escondidos dentro del primero.", "La z de Posició és on comença la peça: el segon pis comença on s'acaba el primer, a 10 mm, i el tercer a 20.|La z de Posición es donde empieza la pieza: el segundo piso empieza donde acaba el primero, a 10 mm, y el tercero a 20."],
      ["A la medalla, l'estrella fa 6 mm d'alt (la mida que surt de la paleta).|En la medalla, la estrella mide 6 mm de alto (la medida que sale de la paleta).", "Que canviï la z de Mida a 1: les 5 capes que falten són 1 mm.|Que cambie la z de Medida a 1: las 5 capas que faltan son 1 mm."]],
    diff: { mes: "Calcular quant tardaria una peça si cada capa trigués un minut; comparar el temps del regle dret i estirat; fer una medalla amb relleu i gravat alhora.|Calcular cuánto tardaría una pieza si cada capa tardara un minuto; comparar el tiempo de la regla de pie y tumbada; hacer una medalla con relieve y grabado a la vez.",
      menys: "Deixar a la pissarra la taula de capes (1 mm = 5, 2 mm = 10, 4 mm = 20) i fer el primer repte junts. A la torre, donar les z escrites.|Dejar en la pizarra la tabla de capas (1 mm = 5, 2 mm = 10, 4 mm = 20) y hacer el primer reto juntos. En la torre, dar las z escritas." },
    aval: { ticket: ['Quantes capes té una peça de 6 mm?|¿Cuántas capas tiene una pieza de 6 mm?', "Per què cada capa necessita alguna cosa a sota?|¿Por qué cada capa necesita algo debajo?"],
      rubric: [['Com treballa la impressora|Cómo trabaja la impresora', 'Explica el camí del filament i que es fa capa a capa de baix a dalt.|Explica el camino del filamento y que se hace capa a capa de abajo arriba.', "Sap que es fa per capes, però li costa explicar el procés.|Sabe que se hace por capas, pero le cuesta explicar el proceso."],
        ['Capes i mesura|Capas y medida', "Calcula les capes d'una peça (× 5) i al revés.|Calcula las capas de una pieza (× 5) y al revés.", 'Confon capes i mil·límetres o necessita la taula.|Confunde capas y milímetros o necesita la tabla.'],
        ['Orientació a la placa|Orientación en la placa', 'Tria posar la peça estirada i explica per què.|Elige poner la pieza tumbada y explica por qué.', "L'estira, però no sap dir què guanya.|La tumba, pero no sabe decir qué gana."]] },
    casa: "Mireu objectes de plàstic de casa: es veuen ratlles de capes? Les peces fetes amb impressora 3D en tenen; les fetes amb motlle, no. Si coneixeu algú que tingui una impressora 3D, demaneu-li que us ensenyi una peça.|Mirad objetos de plástico de casa: ¿se ven rayas de capas? Las piezas hechas con impresora 3D las tienen; las hechas con molde, no. Si conocéis a alguien que tenga una impresora 3D, pedidle que os enseñe una pieza.",
    intro: "Primera sessió de la unitat de la Nuvi: l'alumnat passa de dissenyar a entendre com es fabrica el que dissenya. La idea clau és que la impressora no fa l'objecte de cop, sinó capa a capa de baix a dalt, i que això explica moltes regles de disseny que veuran a la sessió següent.|Primera sesión de la unidad de Nuvi: el alumnado pasa de diseñar a entender cómo se fabrica lo que diseña. La idea clave es que la impresora no hace el objeto de golpe, sino capa a capa de abajo arriba, y que esto explica muchas reglas de diseño que verán en la sesión siguiente.",
    claus: ["La impressora fon el filament al broquet (uns 200 °C) i el posa en línies d'uns 0,4 mm.|La impresora funde el filamento en la boquilla (unos 200 °C) y lo pone en líneas de unos 0,4 mm.", "Imprimeix capa a capa, de baix a dalt: cada capa s'aguanta sobre l'anterior.|Imprime capa a capa, de abajo arriba: cada capa se aguanta sobre la anterior.",
      'Amb capes de 0,2 mm, cada mil·límetre són 5 capes.|Con capas de 0,2 mm, cada milímetro son 5 capas.', "Més capes i més grans vol dir més temps; estirar la peça li treu capes i la fa més estable.|Más capas y más grandes quiere decir más tiempo; tumbar la pieza le quita capas y la hace más estable."],
    prev: ['Saber canviar les mides i la posició d\'una peça amb els camps numèrics.|Saber cambiar las medidas y la posición de una pieza con los campos numéricos.', 'Saber girar una peça a la pestanya Gir (unitat 3).|Saber girar una pieza en la pestaña Giro (unidad 3).', 'Multiplicar per 5 i entendre les dècimes (0,2).|Multiplicar por 5 y entender las décimas (0,2).'],
    faq: [['Quant tarda de debò una impressió?|¿Cuánto tarda de verdad una impresión?', "Depèn de la mida, de l'alçada, del gruix de capa i de quant s'omple per dins. Una medalla petita pot tardar menys d'una hora; un porta-llapis, unes quantes hores. El programa laminador ho calcula abans d'imprimir.|Depende del tamaño, de la altura, del grosor de capa y de cuánto se rellena por dentro. Una medalla pequeña puede tardar menos de una hora; un portalápices, unas cuantas horas. El programa laminador lo calcula antes de imprimir."],
      ["És perillosa una impressora 3D?|¿Es peligrosa una impresora 3D?", "El broquet arriba a uns 200 °C i la placa, si s'escalfa, a uns 60 °C: no s'han de tocar mentre treballa. Feu-la servir sempre amb un adult i en un lloc ventilat.|La boquilla llega a unos 200 °C y la placa, si se calienta, a unos 60 °C: no se tienen que tocar mientras trabaja. Usadla siempre con un adulto y en un lugar ventilado."],
      ['Per què no veiem les capes als models del taller?|¿Por qué no vemos las capas en los modelos del taller?', "Perquè el taller dibuixa l'objecte acabat i llis. Les capes apareixen quan es prepara la impressió: el programa laminador és el que talla el model en capes (ho veurem a la sessió 3).|Porque el taller dibuja el objeto acabado y liso. Las capas aparecen cuando se prepara la impresión: el programa laminador es el que corta el modelo en capas (lo veremos en la sesión 3)."]],
    tec: [['No trobo com girar la peça.|No encuentro cómo girar la pieza.', "És la pestanya Gir de l'inspector. Cada toc del + gira 15°; també es pot escriure el número (90).|Es la pestaña Giro del inspector. Cada toque del + gira 15°; también se puede escribir el número (90)."],
      ["En canviar l'alçada, la peça s'enfonsa a la placa?|Al cambiar la altura, ¿la pieza se hunde en la placa?", "No: el taller manté la base al seu lloc quan canvies una mida. Si la veus enfonsada, revisa la z de Posició.|No: el taller mantiene la base en su sitio cuando cambias una medida. Si la ves hundida, revisa la z de Posición."],
      ['El regle surt de la vista.|La regla sale de la vista.', 'Toqueu el botó de centrar la vista (el quadre amb el punt).|Tocad el botón de centrar la vista (el cuadro con el punto).']],
    extra: ["Fer una línia del temps de la impressió d'una peça: què passa al minut 1, a la meitat i al final.|Hacer una línea del tiempo de la impresión de una pieza: qué pasa en el minuto 1, en la mitad y al final.", 'Comparar amb altres maneres de fabricar: tallar fusta (es treu material) i fer una figura de fang (es dona forma).|Comparar con otras maneras de fabricar: cortar madera (se quita material) y hacer una figura de barro (se da forma).', 'Mesurar les capes d\'una peça impresa amb un regle i una lupa.|Medir las capas de una pieza impresa con una regla y una lupa.'],
    trans: ["Sessió següent: gruix i base plana (què fa que una peça es pugui imprimir).|Sesión siguiente: grosor y base plana (qué hace que una pieza se pueda imprimir).", 'Matemàtiques: els nombres decimals i les mesures en mm.|Matemáticas: los números decimales y las medidas en mm.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Com treballa una impressora 3D|Cómo trabaja una impresora 3D', x: 'La Nuvi fa objectes capa a capa|Nuvi hace objetos capa a capa', nota: "Presenta l'encàrrec: medalles de record per a la classe de 4t de l'Escola del Turó.|Presenta el encargo: medallas de recuerdo para la clase de 4.º de la Escuela del Turó." },
      { id: 's2', k: 'pregunta', t: 'Com es fa un objecte amb una impressora 3D?|¿Cómo se hace un objeto con una impresora 3D?', x: 'Pista: mira una peça impresa amb una lupa.|Pista: mira una pieza impresa con una lupa.', nota: "Recull idees. Si algú diu «de cop», pregunta per què es veuen ratlles.|Recoge ideas. Si alguien dice «de golpe», pregunta por qué se ven rayas." },
      { id: 's3', k: 'anim', t: 'Del filament a la línia|Del filamento a la línea', anim: 'm6broquet', x: 'El broquet, a uns 200 °C, fon el filament.|La boquilla, a unos 200 °C, funde el filamento.', nota: 'Remarca la seguretat: el broquet i la placa cremen.|Remarca la seguridad: la boquilla y la placa queman.' },
      { id: 's4', k: 'anim', t: 'Capa a capa|Capa a capa', anim: 'm6capes', x: 'x i y dibuixen la capa; z puja 0,2 mm.|x e y dibujan la capa; z sube 0,2 mm.', nota: "Relaciona-ho amb els eixos de la unitat 1.|Relaciónalo con los ejes de la unidad 1." },
      { id: 's5', k: 'media', t: 'Quantes capes?|¿Cuántas capas?', x: '20 mm × 5 = 100 capes. Cada franja, 10 capes.|20 mm × 5 = 100 capas. Cada franja, 10 capas.', media: { k: 'model', model: FRANGES }, nota: "Pregunta: i una peça de 4 mm? I una de 50 mm?|Pregunta: ¿y una pieza de 4 mm? ¿Y una de 50 mm?" },
      { id: 's6', k: 'anim', t: 'Quant tardarà?|¿Cuánto tardará?', anim: 'm6temps', x: 'Més capes, més temps. Capes fines: llis però lent.|Más capas, más tiempo. Capas finas: liso pero lento.', nota: "No donis xifres exactes: depèn de la impressora i de la peça.|No des cifras exactas: depende de la impresora y de la pieza." },
      { id: 's7', k: 'media', t: 'Dret o estirat?|¿De pie o tumbado?', x: 'Dret: 500 capes. Estirat: 15.|De pie: 500 capas. Tumbada: 15.', media: { k: 'model', model: REGLES }, nota: 'Gira el model per comparar-los de costat.|Gira el modelo para compararlos de lado.' },
      { id: 's8', k: 'activitat', t: 'Imprimeix amb plastilina|Imprime con plastilina', timer: 7, punts: ['Fes un filament de plastilina.|Haz un filamento de plastilina.', 'Construeix un gotet de 6 capes.|Construye un vasito de 6 capas.', 'Mesura i calcula el gruix de cada capa.|Mide y calcula el grosor de cada capa.'], nota: 'Per parelles. Al final, que provin de treure una capa cap enfora.|Por parejas. Al final, que prueben a sacar una capa hacia fuera.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['La fitxa de 10 capes.|La ficha de 10 capas.', 'La torre de tres pisos.|La torre de tres pisos.', 'El regle estirat.|La regla tumbada.'], nota: 'Primer el càlcul, després el número.|Primero el cálculo, después el número.' },
      { id: 's10', k: 'concepte', t: 'La regla de les capes|La regla de las capas', x: 'Alçada en mm × 5 = capes. 1 mm = 5 capes · 2 mm = 10 · 4 mm = 20 · 10 mm = 50.|Altura en mm × 5 = capas. 1 mm = 5 capas · 2 mm = 10 · 4 mm = 20 · 10 mm = 50.', nota: "Deixa-la a la vista durant els reptes.|Déjala a la vista durante los retos." },
      { id: 's11', k: 'media', t: 'La torre de tres pisos|La torre de tres pisos', x: 'Cada pis fa 10 mm: 50 capes.|Cada piso mide 10 mm: 50 capas.', media: { k: 'model', model: TORRE }, nota: "Ajuda per a qui s'encalli: els pisos comencen a z = 10 i z = 20.|Ayuda para quien se atasque: los pisos empiezan en z = 10 y z = 20." },
      { id: 's12', k: 'repte', t: 'La medalla del Taller|La medalla del Taller', punts: ['Forma i color lliures.|Forma y color libres.', 'Un dibuix en relleu o gravat.|Un dibujo en relieve o grabado.', 'Com a molt 20 capes (4 mm).|Como mucho 20 capas (4 mm).'], nota: "Les comprovacions avisen si la medalla és massa alta.|Las comprobaciones avisan si la medalla es demasiado alta." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['La Nuvi fon el filament i el posa en línies.|Nuvi funde el filamento y lo pone en líneas.', 'Capa a capa, de baix a dalt: 5 capes per mm.|Capa a capa, de abajo arriba: 5 capas por mm.', 'Més capes, més temps; estirada, més estable.|Más capas, más tiempo; tumbada, más estable.'], nota: 'Llegiu-ho junts en veu alta.|Leedlo juntos en voz alta.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Quantes capes té una peça de 6 mm?|¿Cuántas capas tiene una pieza de 6 mm?', 'Per què cada capa necessita alguna cosa a sota?|¿Por qué cada capa necesita algo debajo?'], nota: 'Oral o escrit al darrere de la fitxa.|Oral o escrito detrás de la ficha.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: 'Busca objectes de plàstic amb ratlles de capes.|Busca objetos de plástico con rayas de capas.', nota: 'La sessió següent podeu començar posant-ho en comú.|En la sesión siguiente podéis empezar poniéndolo en común.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: comptem capes|Ficha: contamos capas', k: 'fitxa', intro: "Capes de 0,2 mm: cada mil·límetre són 5 capes.|Capas de 0,2 mm: cada milímetro son 5 capas.",
      items: [{ q: 'Una fitxa fa 2 mm. Quantes capes té?|Una ficha mide 2 mm. ¿Cuántas capas tiene?', sol: '2 × 5 = 10 capes.|2 × 5 = 10 capas.' },
        { q: 'Una torre té 150 capes. Quants mil·límetres fa?|Una torre tiene 150 capas. ¿Cuántos milímetros mide?', sol: '150 ÷ 5 = 30 mm.|150 ÷ 5 = 30 mm.' },
        { q: 'El gotet de plastilina: alçada ____ mm, 6 capes → cada capa fa ____ mm.|El vasito de plastilina: altura ____ mm, 6 capas → cada capa mide ____ mm.', sol: "Resposta oberta: alçada ÷ 6 (sol sortir entre 3 i 6 mm per capa).|Respuesta abierta: altura ÷ 6 (suele salir entre 3 y 6 mm por capa)." },
        { q: 'Un regle de 100 mm: quantes capes té dret? I estirat (3 mm)?|Una regla de 100 mm: ¿cuántas capas tiene de pie? ¿Y tumbada (3 mm)?', sol: 'Dret: 500 capes. Estirat: 15 capes.|De pie: 500 capas. Tumbada: 15 capas.' }] }]
  },
  /* ---------- Sessió 2 · Gruix i base plana ---------- */
  'm6-2': {
    obj: ["L'alumne/a reconeix si una peça té una base plana que s'enganxi a la placa i n'hi posa una si cal.|El alumno/a reconoce si una pieza tiene una base plana que se pegue a la placa y le pone una si hace falta.",
      "L'alumne/a detecta parts que floten i les recolza perquè tot sigui una sola peça.|El alumno/a detecta partes que flotan y las apoya para que todo sea una sola pieza.",
      "L'alumne/a explica per què les parets han de fer almenys 2 mm i en corregeix una de massa prima.|El alumno/a explica por qué las paredes tienen que medir al menos 2 mm y corrige una demasiado fina.",
      "L'alumne/a identifica voladissos de més de 45° que necessiten suports i canvia l'orientació de la peça per evitar-los.|El alumno/a identifica voladizos de más de 45° que necesitan soportes y cambia la orientación de la pieza para evitarlos."],
    comp: ["Tecnologia i digitalització: requisits de fabricació d'un prototip (base, unió de parts, gruix, voladissos)|Tecnología y digitalización: requisitos de fabricación de un prototipo (base, unión de partes, grosor, voladizos)", "Matemàtiques, sentit espacial: angles (45°, 90°) i vistes de costat|Matemáticas, sentido espacial: ángulos (45°, 90°) y vistas de lado",
      "Matemàtiques, sentit de la mesura: gruix de paret, (fora − dins) ÷ 2|Matemáticas, sentido de la medida: grosor de pared, (fuera − dentro) ÷ 2", "Pensament computacional: depurar un model amb una llista de comprovacions|Pensamiento computacional: depurar un modelo con una lista de comprobaciones"],
    vocab: [['Base plana|Base plana', "Cara plana que recolza a la placa i on s'enganxa la primera capa.|Cara plana que se apoya en la placa y donde se pega la primera capa."], ['Peanya|Peana', 'Base ampla que es posa sota una figura perquè s\'aguanti.|Base ancha que se pone bajo una figura para que se aguante.'],
      ['Voladís|Voladizo', "Part que surt cap enfora sense res a sota.|Parte que sale hacia fuera sin nada debajo."], ['Suport|Soporte', "Columna de plàstic que la impressora posa sota un voladís i que després es treu.|Columna de plástico que la impresora pone bajo un voladizo y que después se quita."],
      ['Gruix de paret|Grosor de pared', "Quant fa una paret de banda a banda.|Cuánto mide una pared de lado a lado."], ['Peça connectada|Pieza conectada', 'Model on totes les parts es toquen: es fa d\'una sola peça.|Modelo donde todas las partes se tocan: se hace de una sola pieza.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Gruix i base plana»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Grosor y base plana»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Per grup: 10 monedes iguals (o fitxes), una pilota petita i un got de plàstic|Por grupo: 10 monedas iguales (o fichas), una pelota pequeña y un vaso de plástico'],
      imprimir: ['Fitxa: la revisió de la Nuvi|Ficha: la revisión de Nuvi', "Targetes: s'imprimeix bé?|Tarjetas: ¿se imprime bien?"], prep: ["Si teniu peces impreses amb suports o amb errors (un voladís caigut, fils), portar-les: valen més que mil paraules.|Si tenéis piezas impresas con soportes o con errores (un voladizo caído, hilos), traerlas: valen más que mil palabras.", 'Imprimir i retallar les targetes.|Imprimir y recortar las tarjetas.', 'Provar abans el repte de la torre: cal canviar la x i la y del forat a 16.|Probar antes el reto de la torre: hay que cambiar la x y la y del agujero a 16.'] },
    plan: [
      { min: 5, t: "El club d'escacs|El club de ajedrez", fase: 'inici', fa: "Presenta l'encàrrec: peces noves per al club d'escacs, que tenen errors. Ensenya una peça amb suports o amb un error d'impressió, si en teniu, i pregunta què ha passat.|Presenta el encargo: piezas nuevas para el club de ajedrez, que tienen errores. Enseña una pieza con soportes o con un error de impresión, si tenéis, y pregunta qué ha pasado.",
        diu: ['Quines coses no podria imprimir la Nuvi?|¿Qué cosas no podría imprimir Nuvi?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Les quatre regles|Las cuatro reglas', fase: 'teoria', fa: "Explica les quatre regles amb les animacions: base plana, res a l'aire, parets de 2 mm i voladissos fins a 45°. Mostra el peó en 3D i feu-ne la revisió junts, girant-lo per mirar-lo de costat.|Explica las cuatro reglas con las animaciones: base plana, nada en el aire, paredes de 2 mm y voladizos hasta 45°. Muestra el peón en 3D y haced su revisión juntos, girándolo para mirarlo de lado.",
        diu: ['Per què una bola no és una bona base?|¿Por qué una bola no es una buena base?', 'On posaries suports en aquest bolet?|¿Dónde pondrías soportes en esta seta?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: "L'escala de monedes|La escalera de monedas", fase: 'desconnectat', fa: "En grups: comparen la pilota i el got (base), fan una escala de monedes amb salts petits i grans i en fan una a 45° (salts tan llargs com el gruix de la moneda). Després classifiquen les targetes: s'imprimeix bé o no?|En grupos: comparan la pelota y el vaso (base), hacen una escalera de monedas con saltos pequeños y grandes y hacen una a 45° (saltos tan largos como el grosor de la moneda). Después clasifican las tarjetas: ¿se imprime bien o no?",
        diu: ['Amb quins salts cau abans l\'escala?|¿Con qué saltos se cae antes la escalera?'], slides: ['s8'], app: 'Encara no: monedes i targetes.|Todavía no: monedas y tarjetas.', org: 'En grups de 3|En grupos de 3' },
      { min: 22, t: 'Arreglem les peces|Arreglamos las piezas', fase: 'ordinador', fa: "Fan la sessió a l'app: trien la base que s'enganxa millor, troben el model que necessita suports, baixen la corona, posen una peanya a la bola, engruixeixen les parets de la torre i construeixen el peó. L'alfil cap per avall és un repte extra.|Hacen la sesión en la app: eligen la base que se pega mejor, encuentran el modelo que necesita soportes, bajan la corona, ponen una peana a la bola, engrosan las paredes de la torre y construyen el peón. El alfil boca abajo es un reto extra.",
        diu: ['Quina comprovació falla? Què et diu?|¿Qué comprobación falla? ¿Qué te dice?'], slides: ['s9', 's10', 's11'], app: "Sessió «Gruix i base plana», fins a «La meva peça d'escacs».|Sesión «Grosor y base plana», hasta «Mi pieza de ajedrez».", org: 'Individual|Individual' },
      { min: 8, t: "La meva peça d'escacs|Mi pieza de ajedrez", fase: 'crea', fa: "Cada alumne/a dissenya una peça per al club. Ha de passar la revisió automàtica i, a més, l'han de mirar de costat per buscar voladissos (el taller no els comprova).|Cada alumno/a diseña una pieza para el club. Tiene que pasar la revisión automática y, además, la tienen que mirar de lado para buscar voladizos (el taller no los comprueba).",
        diu: ["Mira-la de costat: hi ha alguna part que surti massa cap enfora?|Mírala de lado: ¿hay alguna parte que salga demasiado hacia fuera?"], slides: ['s12'], app: "Pas «La meva peça d'escacs».|Paso «Mi pieza de ajedrez».", org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa les quatre regles i quines comprova el taller sol. Tiquet de sortida.|Repasa las cuatro reglas y cuáles comprueba el taller solo. Ticket de salida.",
        diu: ['Quina regla et costa més de recordar?|¿Qué regla te cuesta más recordar?'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Al peó de bola, afegeix la peanya però la deixa a part, sense tocar la bola.|En el peón de bola, añade la peana pero la deja aparte, sin tocar la bola.", "Que miri «És una sola peça»: la peanya ha d'anar a x = 0, y = 0, just a sota de la bola.|Que mire «Es una sola pieza»: la peana tiene que ir en x = 0, y = 0, justo debajo de la bola."],
      ["A la torre, canvia la mida del cilindre de fora en lloc de la del forat.|En la torre, cambia la medida del cilindro de fuera en lugar de la del agujero.", "Desfer i tornar-ho a fer amb el forat seleccionat (és gris i ratllat). Calculeu junts: (20 − 16) ÷ 2 = 2 mm.|Deshacer y volver a hacerlo con el agujero seleccionado (es gris y rayado). Calculad juntos: (20 − 16) ÷ 2 = 2 mm."],
      ["Puja la corona en lloc de baixar-la, o la deixa enfonsada dins del cos.|Sube la corona en lugar de bajarla, o la deja hundida dentro del cuerpo.", "La corona ha de començar on s'acaba el coll: a z = 31. Que ho miri a la vista de davant.|La corona tiene que empezar donde acaba el cuello: en z = 31. Que lo mire en la vista de delante."],
      ["Creu que si totes les comprovacions són verdes ja no hi ha voladissos.|Cree que si todas las comprobaciones están en verde ya no hay voladizos.", "Explica-li que el taller no mira els voladissos: és la quarta pregunta de la revisió i l'ha de mirar ell/a de costat.|Explícale que el taller no mira los voladizos: es la cuarta pregunta de la revisión y la tiene que mirar él/ella de lado."]],
    diff: { mes: "Dissenyar un cavall o un rei amb parts que surtin poc a poc (a 45°) en lloc de voladissos; explicar com orientaria a la placa una lletra T perquè no necessiti suports.|Diseñar un caballo o un rey con partes que salgan poco a poco (a 45°) en lugar de voladizos; explicar cómo orientaría en la placa una letra T para que no necesite soportes.",
      menys: "Fer els reptes amb la llista de les quatre preguntes a la vista i fer junts el de la torre. A la peça lliure, partir del peó i canviar-ne només una part.|Hacer los retos con la lista de las cuatro preguntas a la vista y hacer juntos el de la torre. En la pieza libre, partir del peón y cambiar solo una parte." },
    aval: { ticket: ["Per què una bola sola no és una bona base?|¿Por qué una bola sola no es una buena base?", "Fins a quin angle pot sortir una paret sense suports?|¿Hasta qué ángulo puede salir una pared sin soportes?"],
      rubric: [["Base i peces connectades|Base y piezas conectadas", "Posa bases planes i recolza totes les parts sense ajuda.|Pone bases planas y apoya todas las partes sin ayuda.", "Ho arregla quan la comprovació avisa, però no ho preveu.|Lo arregla cuando la comprobación avisa, pero no lo prevé."],
        ['Gruix de paret|Grosor de pared', 'Calcula el gruix de paret i el fa de 2 mm o més.|Calcula el grosor de pared y lo hace de 2 mm o más.', 'Sap la regla dels 2 mm, però li costa calcular-la.|Sabe la regla de los 2 mm, pero le cuesta calcularla.'],
        ['Voladissos|Voladizos', 'Reconeix voladissos de més de 45° i canvia el disseny o l\'orientació.|Reconoce voladizos de más de 45° y cambia el diseño o la orientación.', "Només els veu quan algú els hi assenyala.|Solo los ve cuando alguien se los señala."]] },
    casa: "Busqueu a casa objectes que no es podrien imprimir tal com són (una cadira amb el seient a l'aire, un paraigua obert…). Com els giraríeu o els partiríeu perquè la Nuvi els pogués fer?|Buscad en casa objetos que no se podrían imprimir tal como son (una silla con el asiento en el aire, un paraguas abierto…). ¿Cómo los giraríais o los partiríais para que Nuvi los pudiera hacer?",
    intro: "Sessió de les regles de disseny per imprimir. Les quatre preguntes de la revisió (base plana, una sola peça, parets de 2 mm, voladissos fins a 45°) les faran servir a la resta del curs. El taller comprova les tres primeres; els voladissos els ha de mirar l'alumnat, i és bo que s'acostumin a girar el model i mirar-lo de costat.|Sesión de las reglas de diseño para imprimir. Las cuatro preguntas de la revisión (base plana, una sola pieza, paredes de 2 mm, voladizos hasta 45°) las usarán en el resto del curso. El taller comprueba las tres primeras; los voladizos los tiene que mirar el alumnado, y es bueno que se acostumbren a girar el modelo y mirarlo de lado.",
    claus: ["La primera capa s'ha d'enganxar: cal una base plana i ampla.|La primera capa se tiene que pegar: hace falta una base plana y ancha.", "Res no pot flotar: totes les parts han de recolzar sobre la placa o sobre una altra part.|Nada puede flotar: todas las partes tienen que apoyarse sobre la placa o sobre otra parte.",
      "Parets d'almenys 2 mm: el broquet fa línies d'uns 0,4 mm.|Paredes de al menos 2 mm: la boquilla hace líneas de unos 0,4 mm.", "Voladissos fins a uns 45°; si no, suports (o girar la peça).|Voladizos hasta unos 45°; si no, soportes (o girar la pieza)."],
    prev: ['Haver fet «Com treballa una impressora 3D»: capa a capa, de baix a dalt.|Haber hecho «Cómo trabaja una impresora 3D»: capa a capa, de abajo arriba.', 'Saber fer forats i calcular el gruix de paret (unitat 5).|Saber hacer agujeros y calcular el grosor de pared (unidad 5).', 'Saber girar una peça a la pestanya Gir.|Saber girar una pieza en la pestaña Giro.'],
    faq: [["Per què 45° i no un altre angle?|¿Por qué 45° y no otro ángulo?", "Perquè a 45° cada capa surt cap enfora més o menys tant com fa d'alta, i encara recolza la meitat de la línia sobre la de sota. És una regla aproximada: segons la impressora i el plàstic, es pot anar una mica més enllà.|Porque a 45° cada capa sale hacia fuera más o menos tanto como mide de alta, y todavía apoya la mitad de la línea sobre la de debajo. Es una regla aproximada: según la impresora y el plástico, se puede ir un poco más allá."],
      ["Els suports es poden treure fàcilment?|¿Los soportes se pueden quitar fácilmente?", "Sí, la majoria es treuen amb els dits o amb unes alicates, però deixen marques i gasten plàstic. Per això és millor dissenyar sense voladissos o girar la peça.|Sí, la mayoría se quitan con los dedos o con unos alicates, pero dejan marcas y gastan plástico. Por eso es mejor diseñar sin voladizos o girar la pieza."],
      ["Per què 2 mm si el broquet en fa 0,4?|¿Por qué 2 mm si la boquilla mide 0,4?", "Una paret d'una sola línia es pot fer, però és molt fràgil. Amb 2 mm hi caben unes 5 línies i la peça aguanta cops i caigudes: és una bona regla per a l'aula.|Una pared de una sola línea se puede hacer, pero es muy frágil. Con 2 mm caben unas 5 líneas y la pieza aguanta golpes y caídas: es una buena regla para el aula."]],
    tec: [["La comprovació de parets fa vermell i no sé on és el problema.|La comprobación de paredes sale en rojo y no sé dónde está el problema.", "Mireu el model en mode Resultat i de dalt: les parets fines i les puntes (de cons i estrelles) són els llocs habituals.|Mirad el modelo en modo Resultado y desde arriba: las paredes finas y las puntas (de conos y estrellas) son los sitios habituales."],
      ["«És una sola peça» no es marca i tot sembla enganxat.|«Es una sola pieza» no se marca y todo parece pegado.", "Potser hi ha una peça a una dècima de distància. Feu que entri una mica dins de l'altra o poseu la z exacta.|Quizá hay una pieza a una décima de distancia. Haced que entre un poco dentro de la otra o poned la z exacta."],
      ["En girar el con, la punta queda enfonsada.|Al girar el cono, la punta queda hundida.", "El taller manté la base a lloc en girar. Si queda enfonsat, poseu z = 0 a Posició.|El taller mantiene la base en su sitio al girar. Si queda hundido, poned z = 0 en Posición."]],
    extra: ["Fer un «museu dels errors»: peces impreses que han sortit malament i què les va fer fallar.|Hacer un «museo de los errores»: piezas impresas que han salido mal y qué las hizo fallar.", 'Dibuixar una lletra T, una Y i una L de costat i decidir com posar-les a la placa.|Dibujar una letra T, una Y y una L de lado y decidir cómo ponerlas en la placa.', "Organitzar un torneig d'escacs amb les peces dissenyades (si es poden imprimir).|Organizar un torneo de ajedrez con las piezas diseñadas (si se pueden imprimir)."],
    trans: ["Sessió següent: exportar el fitxer STL (triangles, mida real i escala).|Sesión siguiente: exportar el archivo STL (triángulos, tamaño real y escala).", 'Matemàtiques: els angles i com es mesuren.|Matemáticas: los ángulos y cómo se miden.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Gruix i base plana|Grosor y base plana', x: "Peces noves per al club d'escacs|Piezas nuevas para el club de ajedrez", nota: "Presenta l'encàrrec d'en Ferran.|Presenta el encargo de Ferran." },
      { id: 's2', k: 'pregunta', t: 'Què no podria imprimir la Nuvi?|¿Qué no podría imprimir Nuvi?', x: 'Pensa en com treballa: capa a capa, de baix a dalt.|Piensa en cómo trabaja: capa a capa, de abajo arriba.', nota: "Busqueu exemples: una cosa a l'aire, una paret molt fina, una bola…|Buscad ejemplos: algo en el aire, una pared muy fina, una bola…" },
      { id: 's3', k: 'anim', t: 'Base plana|Base plana', anim: 'm6base', x: 'La bola toca un punt; el cilindre, tota la base.|La bola toca un punto; el cilindro, toda la base.', nota: "Relaciona-ho amb la pilota i el got de l'activitat.|Relaciónalo con la pelota y el vaso de la actividad." },
      { id: 's4', k: 'anim', t: "Res a l'aire|Nada en el aire", anim: 'm6flota', x: "El plàstic a l'aire cau i fa fils.|El plástico en el aire cae y hace hilos.", nota: '«Espaguetis» és el nom que fan servir molts aficionats per a aquest error.|«Espaguetis» es el nombre que usan muchos aficionados para este error.' },
      { id: 's5', k: 'anim', t: 'Parets de 2 mm|Paredes de 2 mm', anim: 'm6paret', x: '1 línia es trenca; 5 línies aguanten.|1 línea se rompe; 5 líneas aguantan.', nota: "Recorda el càlcul de la unitat 5: (fora − dins) ÷ 2.|Recuerda el cálculo de la unidad 5: (fuera − dentro) ÷ 2." },
      { id: 's6', k: 'anim', t: 'Voladissos|Voladizos', anim: 'm6volad', x: 'Fins a 45°, sense ajuda. Més, amb suports.|Hasta 45°, sin ayuda. Más, con soportes.', nota: "Ensenya un bolet o una T: on caldrien suports?|Enseña una seta o una T: ¿dónde harían falta soportes?" },
      { id: 's7', k: 'media', t: 'La revisió del peó|La revisión del peón', x: 'Base plana · una sola peça · parets · voladissos.|Base plana · una sola pieza · paredes · voladizos.', media: { k: 'model', model: PEO(BL) }, nota: 'Gireu-lo i feu les quatre preguntes en veu alta.|Giradlo y haced las cuatro preguntas en voz alta.' },
      { id: 's8', k: 'activitat', t: "L'escala de monedes|La escalera de monedas", timer: 7, punts: ['Pilota o got: quin s\'aguanta?|Pelota o vaso: ¿cuál se aguanta?', 'Escala amb salts petits i grans.|Escalera con saltos pequeños y grandes.', 'Escala a 45° i targetes.|Escalera a 45° y tarjetas.'], nota: 'En grups de 3.|En grupos de 3.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['La corona que flota.|La corona que flota.', 'El peó de bola i la torre prima.|El peón de bola y la torre fina.', 'El peó del club.|El peón del club.'], nota: "Que llegeixin quina comprovació falla abans de tocar res.|Que lean qué comprobación falla antes de tocar nada." },
      { id: 's10', k: 'media', t: 'La corona, recolzada|La corona, apoyada', x: 'El coll s\'acaba a 31 mm: la corona comença a z = 31.|El cuello acaba a 31 mm: la corona empieza en z = 31.', media: { k: 'model', model: REINA(31), view: 'front' }, nota: "Ajuda per a qui s'encalli al primer repte.|Ayuda para quien se atasque en el primer reto." },
      { id: 's11', k: 'media', t: 'Necessita suports?|¿Necesita soportes?', x: 'El barret del bolet surt en horitzontal.|El sombrero de la seta sale en horizontal.', media: { k: 'model', model: BOLET, view: 'front' }, nota: 'Pregunta com el podrien imprimir sense suports (per exemple, de cap per avall).|Pregunta cómo lo podrían imprimir sin soportes (por ejemplo, boca abajo).' },
      { id: 's12', k: 'repte', t: "La meva peça d'escacs|Mi pieza de ajedrez", punts: ['Base plana i ampla.|Base plana y ancha.', "Res a l'aire, voladissos fins a 45°.|Nada en el aire, voladizos hasta 45°.", 'Parets i parts de 2 mm o més.|Paredes y partes de 2 mm o más.'], nota: 'Recorda: el taller no mira els voladissos.|Recuerda: el taller no mira los voladizos.' },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Base plana a la placa.|Base plana en la placa.', "Res a l'aire: una sola peça.|Nada en el aire: una sola pieza.", 'Parets de 2 mm i voladissos fins a 45°.|Paredes de 2 mm y voladizos hasta 45°.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Per què una bola no és una bona base?|¿Por qué una bola no es una buena base?', 'Fins a quin angle sense suports?|¿Hasta qué ángulo sin soportes?'], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Busca objectes que la Nuvi no podria imprimir tal com són.|Busca objetos que Nuvi no podría imprimir tal como son.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: la revisió de la Nuvi|Ficha: la revisión de Nuvi', k: 'fitxa', intro: "Fes la revisió de la teva peça d'escacs abans de desar-la.|Haz la revisión de tu pieza de ajedrez antes de guardarla.",
      items: [{ q: 'Té una base plana i ampla? Quina peça fa de base?|¿Tiene una base plana y ancha? ¿Qué pieza hace de base?', sol: 'Per exemple: un cilindre de 22 mm a sota.|Por ejemplo: un cilindro de 22 mm debajo.' },
        { q: 'És una sola peça? Hi ha res que floti?|¿Es una sola pieza? ¿Hay algo que flote?', sol: "Totes les parts es toquen: cap no és a l'aire.|Todas las partes se tocan: ninguna está en el aire." },
        { q: 'Quina és la paret o la part més prima? Quant fa?|¿Cuál es la pared o la parte más fina? ¿Cuánto mide?', sol: 'Ha de fer 2 mm o més.|Tiene que medir 2 mm o más.' },
        { q: 'Mirada de costat: hi ha voladissos de més de 45°? On?|Mirada de lado: ¿hay voladizos de más de 45°? ¿Dónde?', sol: "Resposta oberta: si n'hi ha, cal canviar el disseny o girar la peça.|Respuesta abierta: si hay, hay que cambiar el diseño o girar la pieza." }] },
      { id: 'p2', t: "Targetes: s'imprimeix bé?|Tarjetas: ¿se imprime bien?", k: 'targetes', intro: "Retalleu-les i classifiqueu-les: s'imprimeix bé tal com és, o cal canviar-la?|Recortadlas y clasificadlas: ¿se imprime bien tal como es, o hay que cambiarla?",
        items: [{ t: 'Un got de 2 mm de paret|Un vaso de 2 mm de pared', n: 1 }, { t: 'Una bola sola|Una bola sola', n: 1 }, { t: 'Un bolet amb barret pla|Una seta con sombrero plano', n: 1 }, { t: 'Una piràmide|Una pirámide', n: 1 }, { t: 'Una paret de 0,5 mm|Una pared de 0,5 mm', n: 1 }, { t: 'Una corona que flota|Una corona que flota', n: 1 }, { t: 'Un con amb la punta amunt|Un cono con la punta arriba', n: 1 }, { t: 'Un con amb la punta avall|Un cono con la punta abajo', n: 1 }] }]
  },
  /* ---------- Sessió 3 · Exportar el fitxer STL ---------- */
  'm6-3': {
    obj: ["L'alumne/a explica que un fitxer STL descriu la superfície d'un model amb triangles i que les corbes en necessiten molts.|El alumno/a explica que un archivo STL describe la superficie de un modelo con triángulos y que las curvas necesitan muchos.",
      "L'alumne/a sap que l'STL no guarda colors ni unitats i que les impressores entenen els números com a mil·límetres.|El alumno/a sabe que el STL no guarda colores ni unidades y que las impresoras entienden los números como milímetros.",
      "L'alumne/a escala una peça proporcionalment (× 10, 1:5, 2:1) i comprova que fa la mida real que es demana.|El alumno/a escala una pieza proporcionalmente (× 10, 1:5, 2:1) y comprueba que mide el tamaño real que se pide.",
      "L'alumne/a descarrega el fitxer STL d'un model des del taller o des de «Projectes».|El alumno/a descarga el archivo STL de un modelo desde el taller o desde «Proyectos»."],
    comp: ["Tecnologia i digitalització: formats de fitxer per a la fabricació digital i el camí del disseny a la impressora|Tecnología y digitalización: formatos de archivo para la fabricación digital y el camino del diseño a la impresora", 'Matemàtiques, sentit espacial: polígons, triangles i cares dels cossos geomètrics|Matemáticas, sentido espacial: polígonos, triángulos y caras de los cuerpos geométricos',
      'Matemàtiques, sentit de la mesura: mm i cm, escales (1:5, 2:1) i proporcionalitat|Matemáticas, sentido de la medida: mm y cm, escalas (1:5, 2:1) y proporcionalidad', 'Competència digital: desar, anomenar i compartir fitxers|Competencia digital: guardar, nombrar y compartir archivos'],
    vocab: [['STL|STL', "Tipus de fitxer que descriu la superfície d'un model 3D amb triangles.|Tipo de archivo que describe la superficie de un modelo 3D con triángulos."], ['Triangle|Triángulo', 'Polígon de tres costats: la peça més petita de la superfície d\'un STL.|Polígono de tres lados: la pieza más pequeña de la superficie de un STL.'],
      ['Mida real|Tamaño real', "La mida que tindrà l'objecte de veritat, en mm.|El tamaño que tendrá el objeto de verdad, en mm."], ['Escala|Escala', "Relació entre la mida del model i la de l'original: 1:5 és cinc vegades més petit; 2:1, el doble.|Relación entre el tamaño del modelo y el del original: 1:5 es cinco veces más pequeño; 2:1, el doble."],
      ['Proporcional|Proporcional', 'Que totes les mides canvien pel mateix número i la forma no es deforma.|Que todas las medidas cambian por el mismo número y la forma no se deforma.'], ['Laminador|Laminador', "Programa que talla l'STL en capes i prepara les instruccions per a la impressora.|Programa que corta el STL en capas y prepara las instrucciones para la impresora."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Exportar el fitxer STL»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Exportar el archivo STL»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Paper quadriculat, tisores, cola i retoladors|Papel cuadriculado, tijeras, pegamento y rotuladores'],
      imprimir: ['Fitxa: triangles i escala|Ficha: triángulos y escala'], prep: ["Comprovar que els ordinadors deixen descarregar fitxers (el botó STL baixa un fitxer .stl a la carpeta de baixades).|Comprobar que los ordenadores dejan descargar archivos (el botón STL baja un archivo .stl a la carpeta de descargas).", "Si teniu un programa laminador instal·lat, obrir-hi un STL per ensenyar les capes.|Si tenéis un programa laminador instalado, abrir en él un STL para enseñar las capas.", 'Provar abans el repte de la xapa: cal activar Proporcional.|Probar antes el reto de la chapa: hay que activar Proporcional.'] },
    plan: [
      { min: 5, t: "Un paquet per a l'Escola del Pont|Un paquete para la Escuela del Puente", fase: 'inici', fa: "Presenta l'encàrrec: enviar els dissenys a una altra escola que també té impressora. Pregunta com ho farien sense portar-hi la Nuvi.|Presenta el encargo: enviar los diseños a otra escuela que también tiene impresora. Pregunta cómo lo harían sin llevar a Nuvi.",
        diu: ["Com podem enviar un objecte sense enviar l'objecte?|¿Cómo podemos enviar un objeto sin enviar el objeto?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Triangles, unitats i escala|Triángulos, unidades y escala', fase: 'teoria', fa: "Explica què és un STL amb el cub de 12 triangles i les corbes. Mostra el peó de colors i pregunta com quedarà a l'STL. Explica l'error dels centímetres i l'escala, i el camí complet fins a la impressora.|Explica qué es un STL con el cubo de 12 triángulos y las curvas. Muestra el peón de colores y pregunta cómo quedará en el STL. Explica el error de los centímetros y la escala, y el camino completo hasta la impresora.",
        diu: ['Quants triangles té un cub? I una piràmide de base quadrada?|¿Cuántos triángulos tiene un cubo? ¿Y una pirámide de base cuadrada?', "Si una peça de 4 cm es fa en mm per error, quant farà?|Si una pieza de 4 cm se hace en mm por error, ¿cuánto medirá?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'El cub de 12 triangles|El cubo de 12 triángulos', fase: 'desconnectat', fa: "Dibuixen el desenvolupament d'un cub en paper quadriculat, tracen una diagonal a cada cara i el munten: compten els 12 triangles. Després dibuixen un cercle amb 6 i amb 12 triangles i els comparen.|Dibujan el desarrollo de un cubo en papel cuadriculado, trazan una diagonal en cada cara y lo montan: cuentan los 12 triángulos. Después dibujan un círculo con 6 y con 12 triángulos y los comparan.",
        diu: ['Quin cercle sembla més rodó? Per què?|¿Qué círculo parece más redondo? ¿Por qué?'], slides: ['s8'], app: 'Encara no: paper i tisores.|Todavía no: papel y tijeras.', org: 'Individual|Individual' },
      { min: 22, t: 'Mida real i escala|Tamaño real y escala', fase: 'ordinador', fa: "Fan la sessió a l'app: compten triangles, trien com quedarà el peó a l'STL, escalen la xapa ×10 i l'estrella 1:5, fan la medalla a mida real i en descarreguen l'STL. El peó gegant (2:1) és un repte extra.|Hacen la sesión en la app: cuentan triángulos, eligen cómo quedará el peón en el STL, escalan la chapa ×10 y la estrella 1:5, hacen la medalla a tamaño real y descargan su STL. El peón gigante (2:1) es un reto extra.",
        diu: ['Has activat Proporcional? Mira si el gruix també ha canviat.|¿Has activado Proporcional? Mira si el grosor también ha cambiado.'], slides: ['s9', 's10', 's11'], app: "Sessió «Exportar el fitxer STL», fins a «El regal per a l'Escola del Pont».|Sesión «Exportar el archivo STL», hasta «El regalo para la Escuela del Puente».", org: 'Individual|Individual' },
      { min: 8, t: "El regal per a l'Escola del Pont|El regalo para la Escuela del Puente", fase: 'crea', fa: "Cada alumne/a dissenya una xapa, un clauer o una medalla de com a molt 50 × 50 × 5 mm, la desa i en descarrega l'STL amb un nom clar (per exemple, el seu nom i el de l'objecte).|Cada alumno/a diseña una chapa, un llavero o una medalla de como mucho 50 × 50 × 5 mm, la guarda y descarga su STL con un nombre claro (por ejemplo, su nombre y el del objeto).",
        diu: ['Com sabrà la Lídia que el fitxer és teu?|¿Cómo sabrá Lídia que el archivo es tuyo?'], slides: ['s12'], app: "Pas «El regal per a l'Escola del Pont».|Paso «El regalo para la Escuela del Puente».", org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa què guarda i què no guarda un STL, i com s'escala. Tiquet de sortida.|Repasa qué guarda y qué no guarda un STL, y cómo se escala. Ticket de salida.",
        diu: ["Digues una cosa que l'STL guarda i una que no.|Di una cosa que el STL guarda y una que no."], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Escala només l'amplada i la xapa queda prima com un paper.|Escala solo el ancho y la chapa queda fina como un papel.", "Que activi Proporcional abans d'escriure el número: així totes les mides es multipliquen igual.|Que active Proporcional antes de escribir el número: así todas las medidas se multiplican igual."],
      ["Creu que si pinta el model de colors, la impressora el farà de colors.|Cree que si pinta el modelo de colores, la impresora lo hará de colores.", "L'STL només guarda la forma. El color depèn del filament que es posi a la impressora.|El STL solo guarda la forma. El color depende del filamento que se ponga en la impresora."],
      ["Al peó gegant, escala les peces però no les puja: queden enfonsades l'una dins de l'altra.|En el peón gigante, escala las piezas pero no las sube: quedan hundidas una dentro de otra.", "A escala 2:1, també es dupliquen les alçades on comença cada peça: el con a z = 8 i el cap a z = 36.|A escala 2:1, también se duplican las alturas donde empieza cada pieza: el cono en z = 8 y la cabeza en z = 36."],
      ["No troba el fitxer descarregat.|No encuentra el archivo descargado.", "Mireu la carpeta de baixades del navegador. El fitxer porta el nom del projecte i acaba en .stl.|Mirad la carpeta de descargas del navegador. El archivo lleva el nombre del proyecto y acaba en .stl."]],
    diff: { mes: "Calcular quants triangles té una piràmide de base quadrada (6) o un prisma hexagonal (20); escalar la medalla 1:2 i dir quant plàstic gasta (la vuitena part).|Calcular cuántos triángulos tiene una pirámide de base cuadrada (6) o un prisma hexagonal (20); escalar la medalla 1:2 y decir cuánto plástico gasta (la octava parte).",
      menys: "Fer junts la xapa ×10 a la pissarra, ensenyant on és el botó Proporcional. Donar la medalla amb el forat ja posat i només ajustar-ne les mides.|Hacer juntos la chapa ×10 en la pizarra, enseñando dónde está el botón Proporcional. Dar la medalla con el agujero ya puesto y solo ajustar sus medidas." },
    aval: { ticket: ['Què guarda un fitxer STL? Què no hi guarda?|¿Qué guarda un archivo STL? ¿Qué no guarda?', 'Una peça fa 4 mm i n\'havia de fer 40. Què fas?|Una pieza mide 4 mm y tenía que medir 40. ¿Qué haces?'],
      rubric: [['Què és un STL|Qué es un STL', 'Explica que és una superfície de triangles, sense colors ni unitats.|Explica que es una superficie de triángulos, sin colores ni unidades.', 'Sap que és el fitxer per imprimir, però no què hi ha dins.|Sabe que es el archivo para imprimir, pero no qué hay dentro.'],
        ['Escala|Escala', 'Escala amb Proporcional i comprova les mides finals.|Escala con Proporcional y comprueba las medidas finales.', "Canvia només una mida o no comprova el resultat.|Cambia solo una medida o no comprueba el resultado."],
        ['Exportar|Exportar', "Descarrega l'STL amb un nom clar i sap on el troba.|Descarga el STL con un nombre claro y sabe dónde lo encuentra.", "El descarrega amb ajuda.|Lo descarga con ayuda."]] },
    casa: "Expliqueu a casa per què una impressora no pot saber de quin color és el vostre model si només li envieu l'STL. Busqueu un objecte de casa i escriviu-ne la mida real en mm i en cm.|Explicad en casa por qué una impresora no puede saber de qué color es vuestro modelo si solo le enviáis el STL. Buscad un objeto de casa y escribid su tamaño real en mm y en cm.",
    intro: "Sessió del pas del taller a la impressora: què hi ha dins d'un STL i com s'assegura que una peça surt a la mida real. Les idees de triangles i d'escala connecten molt bé amb les matemàtiques; la part pràctica (descarregar el fitxer i posar-li un bon nom) també és competència digital.|Sesión del paso del taller a la impresora: qué hay dentro de un STL y cómo se asegura que una pieza sale a tamaño real. Las ideas de triángulos y de escala conectan muy bien con las matemáticas; la parte práctica (descargar el archivo y ponerle un buen nombre) también es competencia digital.",
    claus: ["Un STL descriu la superfície amb triangles: un cub en té 12.|Un STL describe la superficie con triángulos: un cubo tiene 12.", "Les corbes es fan amb molts triangles petits.|Las curvas se hacen con muchos triángulos pequeños.",
      "L'STL no guarda ni colors ni unitats: s'entén que són mm.|El STL no guarda ni colores ni unidades: se entiende que son mm.", "Escalar és multiplicar totes les mides pel mateix número.|Escalar es multiplicar todas las medidas por el mismo número."],
    prev: ['Haver fet «Gruix i base plana»: la revisió abans d\'imprimir.|Haber hecho «Grosor y base plana»: la revisión antes de imprimir.', 'Saber canviar les mides d\'una peça i usar el botó Proporcional (unitat 3).|Saber cambiar las medidas de una pieza y usar el botón Proporcional (unidad 3).', 'Saber passar de cm a mm (× 10).|Saber pasar de cm a mm (× 10).'],
    faq: [["Hi ha altres tipus de fitxer per imprimir?|¿Hay otros tipos de archivo para imprimir?", "Sí: n'hi ha que també guarden colors i materials (com el 3MF), però l'STL és el més conegut i gairebé tots els programes l'obren.|Sí: hay algunos que también guardan colores y materiales (como el 3MF), pero el STL es el más conocido y casi todos los programas lo abren."],
      ["Per què el fitxer d'una peça rodona ocupa més?|¿Por qué el archivo de una pieza redonda ocupa más?", "Perquè necessita molts més triangles per semblar rodona. Una caixa en té 12; un cilindre ben llis en pot tenir centenars.|Porque necesita muchos más triángulos para parecer redonda. Una caja tiene 12; un cilindro bien liso puede tener cientos."],
      ["Què fa el programa laminador?|¿Qué hace el programa laminador?", "Obre l'STL, el talla en capes, decideix com s'omple per dins i si calen suports, i calcula el camí del broquet. El resultat és un fitxer d'instruccions que la impressora segueix.|Abre el STL, lo corta en capas, decide cómo se rellena por dentro y si hacen falta soportes, y calcula el camino de la boquilla. El resultado es un archivo de instrucciones que la impresora sigue."]],
    tec: [["No veig el botó STL.|No veo el botón STL.", "Surt a sota de la vista 3D als passos que el permeten (la medalla i el projecte) i a «Projectes», quan obres un projecte desat.|Sale debajo de la vista 3D en los pasos que lo permiten (la medalla y el proyecto) y en «Proyectos», cuando abres un proyecto guardado."],
      ["El botó Proporcional no fa res.|El botón Proporcional no hace nada.", "Primer activeu-lo (queda ressaltat) i després escriviu el número a una de les mides: les altres canvien soles.|Primero activadlo (queda resaltado) y después escribid el número en una de las medidas: las otras cambian solas."],
      ["L'ordinador diu que no pot obrir el fitxer .stl.|El ordenador dice que no puede abrir el archivo .stl.", "És normal si no hi ha cap programa 3D instal·lat: el fitxer és per a la impressora o per a un laminador. No cal obrir-lo per enviar-lo.|Es normal si no hay ningún programa 3D instalado: el archivo es para la impresora o para un laminador. No hace falta abrirlo para enviarlo."]],
    extra: ["Fer una «biblioteca de fitxers» de la classe: una carpeta compartida amb els STL i un nom clar per a cadascun.|Hacer una «biblioteca de archivos» de la clase: una carpeta compartida con los STL y un nombre claro para cada uno.", 'Construir altres poliedres de paper i comptar-ne els triangles (piràmide, prisma).|Construir otros poliedros de papel y contar sus triángulos (pirámide, prisma).', "Fer maquetes a escala d'objectes de l'aula (1:10) i comparar-les.|Hacer maquetas a escala de objetos del aula (1:10) y compararlas."],
    trans: ['Sessió següent: el projecte del porta-llapis, amb tot el que hem après.|Sesión siguiente: el proyecto del portalápices, con todo lo que hemos aprendido.', 'Matemàtiques: la proporcionalitat i les escales dels mapes.|Matemáticas: la proporcionalidad y las escalas de los mapas.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Exportar el fitxer STL|Exportar el archivo STL', x: "Un paquet per a l'Escola del Pont|Un paquete para la Escuela del Puente", nota: "Presenta l'encàrrec de la Lídia.|Presenta el encargo de Lídia." },
      { id: 's2', k: 'pregunta', t: "Com enviem un objecte sense enviar l'objecte?|¿Cómo enviamos un objeto sin enviar el objeto?", x: "L'altra escola també té impressora…|La otra escuela también tiene impresora…", nota: "Arribeu a la idea: enviem el disseny en un fitxer.|Llegad a la idea: enviamos el diseño en un archivo." },
      { id: 's3', k: 'anim', t: 'Què és un STL?|¿Qué es un STL?', anim: 'm6stl', x: 'Una superfície de triangles: un cub en té 12.|Una superficie de triángulos: un cubo tiene 12.', nota: 'Feu el càlcul junts: 6 cares × 2.|Haced el cálculo juntos: 6 caras × 2.' },
      { id: 's4', k: 'anim', t: 'Corbes amb triangles|Curvas con triángulos', anim: 'm6corba', x: 'Com més triangles, més rodó.|Cuantos más triángulos, más redondo.', nota: 'Connecta-ho amb els polígons regulars.|Conéctalo con los polígonos regulares.' },
      { id: 's5', k: 'media', t: 'Només la forma|Solo la forma', x: "L'STL no guarda colors ni unitats.|El STL no guarda colores ni unidades.", media: { k: 'model', model: PEO_COL }, nota: "Pregunta: de quin color sortirà? Del filament!|Pregunta: ¿de qué color saldrá? ¡Del filamento!" },
      { id: 's6', k: 'anim', t: 'Mida real i escala|Tamaño real y escala', anim: 'm6escala', x: 'Pensat en cm: ×10. El doble: 8 vegades més plàstic.|Pensado en cm: ×10. El doble: 8 veces más plástico.', nota: "Construïu el cub doble amb 8 cubs petits si en teniu.|Construid el cubo doble con 8 cubos pequeños si tenéis." },
      { id: 's7', k: 'anim', t: "Del fitxer a l'objecte|Del archivo al objeto", anim: 'm6cami', x: 'Taller → STL → laminador → impressora.|Taller → STL → laminador → impresora.', nota: "Si teniu un laminador, ensenyeu-hi un STL tallat en capes.|Si tenéis un laminador, enseñad en él un STL cortado en capas." },
      { id: 's8', k: 'activitat', t: 'El cub de 12 triangles|El cubo de 12 triángulos', timer: 7, punts: ['Dibuixa i retalla el desenvolupament.|Dibuja y recorta el desarrollo.', 'Una diagonal a cada cara.|Una diagonal en cada cara.', 'Cercles de 6 i de 12 triangles.|Círculos de 6 y de 12 triángulos.'], nota: 'Individual. Compteu els triangles en veu alta.|Individual. Contad los triángulos en voz alta.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['La xapa ×10.|La chapa ×10.', "L'estrella 1:5.|La estrella 1:5.", 'La medalla a mida real.|La medalla a tamaño real.'], nota: 'Recorda: Proporcional abans del número.|Recuerda: Proporcional antes del número.' },
      { id: 's10', k: 'concepte', t: 'El botó Proporcional|El botón Proporcional', x: "Activa'l i escriu una mida: les altres es multipliquen pel mateix número. 4 → 40 vol dir × 10.|Actívalo y escribe una medida: las otras se multiplican por el mismo número. 4 → 40 quiere decir × 10.", nota: 'Demostra-ho a la pissarra amb la xapa.|Demuéstralo en la pizarra con la chapa.' },
      { id: 's11', k: 'media', t: 'La medalla a mida real|La medalla a tamaño real', x: '50 mm de diàmetre, 3 mm de gruix i un forat de 5 mm a (0, 19).|50 mm de diámetro, 3 mm de grosor y un agujero de 5 mm en (0, 19).', media: { k: 'model', model: MED50, view: 'top' }, nota: "Ajuda per a qui s'encalli. El botó STL és a sota de la vista.|Ayuda para quien se atasque. El botón STL está debajo de la vista." },
      { id: 's12', k: 'repte', t: "El regal per a l'Escola del Pont|El regalo para la Escuela del Puente", punts: ['Com a molt 50 × 50 × 5 mm.|Como mucho 50 × 50 × 5 mm.', 'Llest per imprimir.|Listo para imprimir.', 'Descarrega l\'STL amb un nom clar.|Descarga el STL con un nombre claro.'], nota: "Si cal, reuniu els fitxers en una carpeta per enviar-los.|Si hace falta, reunid los archivos en una carpeta para enviarlos." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["L'STL és una superfície de triangles.|El STL es una superficie de triángulos.", 'Sense colors ni unitats: es llegeix en mm.|Sin colores ni unidades: se lee en mm.', 'Escalar: totes les mides pel mateix número.|Escalar: todas las medidas por el mismo número.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Què guarda i què no guarda un STL?|¿Qué guarda y qué no guarda un STL?", 'De 4 mm a 40 mm: què fas?|De 4 mm a 40 mm: ¿qué haces?'], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: 'Mesura un objecte de casa i escriu-ne la mida en mm i en cm.|Mide un objeto de casa y escribe su tamaño en mm y en cm.', nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: triangles i escala|Ficha: triángulos y escala', k: 'fitxa', intro: "Respon després de l'activitat del cub.|Responde después de la actividad del cubo.",
      items: [{ q: "Quants triangles té l'STL d'un cub? Per què?|¿Cuántos triángulos tiene el STL de un cubo? ¿Por qué?", sol: '12: 6 cares × 2 triangles.|12: 6 caras × 2 triángulos.' },
        { q: "Un cercle fet de 6 triangles o de 12: quin és més rodó?|Un círculo hecho de 6 triángulos o de 12: ¿cuál es más redondo?", sol: 'El de 12: com més triangles, més rodó.|El de 12: cuantos más triángulos, más redondo.' },
        { q: "Una xapa de 4 mm havia de fer 4 cm. Per quant l'has de multiplicar?|Una chapa de 4 mm tenía que medir 4 cm. ¿Por cuánto la tienes que multiplicar?", sol: '× 10: 4 mm → 40 mm.|× 10: 4 mm → 40 mm.' },
        { q: "Una estrella de 300 mm a escala 1:5. Quant farà?|Una estrella de 300 mm a escala 1:5. ¿Cuánto medirá?", sol: '300 ÷ 5 = 60 mm.|300 ÷ 5 = 60 mm.' }] }]
  },
  /* ---------- Sessió 4 · Projecte: el porta-llapis ---------- */
  'm6-4': {
    obj: ["L'alumne/a mesura un objecte real (el llapis) i en dedueix la mida del forat amb marge.|El alumno/a mide un objeto real (el lápiz) y deduce el tamaño del agujero con margen.",
      "L'alumne/a calcula el gruix de paret entre dos forats (distància entre centres − diàmetre) i el fa de 2 mm o més.|El alumno/a calcula el grosor de pared entre dos agujeros (distancia entre centros − diámetro) y lo hace de 2 mm o más.",
      "L'alumne/a fa forats amb fons de 2 mm i els duplica en un patró de dues files de tres.|El alumno/a hace agujeros con fondo de 2 mm y los duplica en un patrón de dos filas de tres.",
      "L'alumne/a dissenya un porta-llapis propi llest per imprimir, el desa al portafoli i en pot descarregar l'STL.|El alumno/a diseña un portalápices propio listo para imprimir, lo guarda en el portafolio y puede descargar su STL."],
    comp: ["Tecnologia i digitalització: projecte de disseny i fabricació d'un objecte útil amb requisits mesurables|Tecnología y digitalización: proyecto de diseño y fabricación de un objeto útil con requisitos medibles", 'Matemàtiques, sentit de la mesura: mesurar amb el regle en mm, marges i diferències|Matemáticas, sentido de la medida: medir con la regla en mm, márgenes y diferencias',
      "Matemàtiques, sentit espacial: patrons a la quadrícula i vistes (dalt i tallat)|Matemáticas, sentido espacial: patrones en la cuadrícula y vistas (arriba y cortado)", 'Educació en valors: un objecte pensat per a les persones d\'una taula|Educación en valores: un objeto pensado para las personas de una mesa'],
    vocab: [['Marge|Margen', "Espai de més que es deixa perquè una cosa entri i surti fàcilment.|Espacio de más que se deja para que algo entre y salga fácilmente."], ['De cara a cara|De cara a cara', "Mida d'un llapis de sis cares entre dues cares planes oposades.|Medida de un lápiz de seis caras entre dos caras planas opuestas."],
      ['De punta a punta|De punta a punta', "Mida entre dues cantonades oposades: és la més gran.|Medida entre dos esquinas opuestas: es la más grande."], ['Fons|Fondo', "El plàstic que queda sota d'un forat que no travessa.|El plástico que queda bajo un agujero que no atraviesa."],
      ['Distància entre centres|Distancia entre centros', 'El que hi ha del centre d\'un forat al centre del següent.|Lo que hay del centro de un agujero al centro del siguiente.'], ['Prototip|Prototipo', "Primera versió d'un objecte per provar si funciona.|Primera versión de un objeto para probar si funciona."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: el porta-llapis»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: el portalápices»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Un llapis, un regle, un compàs i paper quadriculat per alumne/a|Un lápiz, una regla, un compás y papel cuadriculado por alumno/a'],
      imprimir: ['Fitxa: el meu porta-llapis|Ficha: mi portalápices', 'Fitxa: la prova de veritat|Ficha: la prueba de verdad'], prep: ["Tenir llapis de diferents gruixos (normals i de colors gruixuts) perquè vegin que no tots fan el mateix.|Tener lápices de distintos grosores (normales y de colores gruesos) para que vean que no todos miden lo mismo.", "Si podeu imprimir, triar amb la classe 2 o 3 porta-llapis per imprimir-los (cadascun pot tardar unes quantes hores).|Si podéis imprimir, elegir con la clase 2 o 3 portalápices para imprimirlos (cada uno puede tardar unas cuantas horas).", "Provar abans el repte dels sis forats: duplicar, moure i tornar a duplicar.|Probar antes el reto de los seis agujeros: duplicar, mover y volver a duplicar."] },
    plan: [
      { min: 5, t: 'Sis llapis per taula|Seis lápices por mesa', fase: 'inici', fa: "Presenta el projecte: un porta-llapis per a cada taula de 6 de la classe de 3r. Pregunta què ha de tenir perquè funcioni i fes una llista a la pissarra.|Presenta el proyecto: un portalápices para cada mesa de 6 de la clase de 3.º. Pregunta qué tiene que tener para que funcione y haz una lista en la pizarra.",
        diu: ['Què ha de tenir un bon porta-llapis?|¿Qué tiene que tener un buen portalápices?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Mides reals, fons i parets|Medidas reales, fondo y paredes', fase: 'teoria', fa: "Explica les mides del llapis i per què el forat fa 9 mm. Mostra el porta-llapis tallat (fons i parets) i les dues maneres de repartir els llapis. Calculeu junts la paret entre dos forats (12 − 9 = 3).|Explica las medidas del lápiz y por qué el agujero mide 9 mm. Muestra el portalápices cortado (fondo y paredes) y las dos maneras de repartir los lápices. Calculad juntos la pared entre dos agujeros (12 − 9 = 3).",
        diu: ['Per què no fem el forat de 8 mm justos?|¿Por qué no hacemos el agujero de 8 mm justos?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'Mesura el teu llapis|Mide tu lápiz', fase: 'desconnectat', fa: "Cada alumne/a mesura el seu llapis (cara a cara, punta a punta i llargada) i dibuixa el porta-llapis vist des de dalt a mida real, amb el compàs. Ho comparen per parelles.|Cada alumno/a mide su lápiz (cara a cara, punta a punta y largo) y dibuja el portalápices visto desde arriba a tamaño real, con el compás. Lo comparan por parejas.",
        diu: ['El teu llapis fa el mateix que el del company?|¿Tu lápiz mide lo mismo que el del compañero?'], slides: ['s8'], app: 'Encara no: regle, compàs i fitxa.|Todavía no: regla, compás y ficha.', org: 'Individual i per parelles|Individual y por parejas' },
      { min: 17, t: 'El porta-llapis pas a pas|El portalápices paso a paso', fase: 'ordinador', fa: "Fan la sessió a l'app: trien el forat del llapis, troben el forat sense fons, fan el primer forat, els sis forats, arreglen el porta-llapis sense fons i, com a extra, hi posen la safata de la goma.|Hacen la sesión en la app: eligen el agujero del lápiz, encuentran el agujero sin fondo, hacen el primer agujero, los seis agujeros, arreglan el portalápices sin fondo y, como extra, le ponen la bandeja de la goma.",
        diu: ['On comença el forat? Queda fons?|¿Dónde empieza el agujero? ¿Queda fondo?'], slides: ['s9', 's10'], app: 'Sessió «Projecte: el porta-llapis», fins a «El porta-llapis de la taula».|Sesión «Proyecto: el portalápices», hasta «El portalápices de la mesa».', org: 'Individual|Individual' },
      { min: 15, t: 'El porta-llapis de la taula|El portalápices de la mesa', fase: 'crea', fa: "Projecte de la unitat: cada alumne/a dissenya el seu porta-llapis (sis forats, un got o una altra idea) a partir del dibuix en paper. Revisa amb ells els criteris (6 llapis, fons i parets de 2 mm, base, alçada) abans de desar-lo, i que en descarreguin l'STL.|Proyecto de la unidad: cada alumno/a diseña su portalápices (seis agujeros, un vaso u otra idea) a partir del dibujo en papel. Revisa con ellos los criterios (6 lápices, fondo y paredes de 2 mm, base, altura) antes de guardarlo, y que descarguen su STL.",
        diu: ['Hi caben els 6 llapis? Com ho saps?|¿Caben los 6 lápices? ¿Cómo lo sabes?'], slides: ['s11', 's12'], app: 'Pas «El porta-llapis de la taula».|Paso «El portalápices de la mesa».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament i galeria|Cierre y galería', fase: 'tancament', fa: "Galeria ràpida: alguns alumnes ensenyen el seu porta-llapis a la pissarra i la classe fa la revisió de la Nuvi en veu alta. Tiquet de sortida.|Galería rápida: algunos alumnos enseñan su portalápices en la pizarra y la clase hace la revisión de Nuvi en voz alta. Ticket de salida.",
        diu: ['Quin imprimiríeu primer? Per què?|¿Cuál imprimiríais primero? ¿Por qué?'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Fa el forat de 8 mm justos (o de 7, com el llapis de cara a cara).|Hace el agujero de 8 mm justos (o de 7, como el lápiz de cara a cara).", "Recorda les mides: de punta a punta fa 8 mm i cal marge per entrar i sortir. 9 mm és la mida bona.|Recuerda las medidas: de punta a punta mide 8 mm y hace falta margen para entrar y salir. 9 mm es la medida buena."],
      ["El primer forat queda amagat dins del bloc (fa 20 mm d'alt i no arriba a dalt).|El primer agujero queda escondido dentro del bloque (mide 20 mm de alto y no llega arriba).", "A Mida, la z ha de ser 40: així surt per dalt del bloc. Que ho miri amb el botó Resultat.|En Medida, la z tiene que ser 40: así sale por arriba del bloque. Que lo mire con el botón Resultado."],
      ["En duplicar, les còpies queden enganxades o massa juntes i la paret fa menys de 2 mm.|Al duplicar, las copias quedan pegadas o demasiado juntas y la pared mide menos de 2 mm.", "Que escrigui les x exactes (−12, 0, 12) a Posició: 12 − 9 = 3 mm de paret.|Que escriba las x exactas (−12, 0, 12) en Posición: 12 − 9 = 3 mm de pared."],
      ["Al projecte lliure, fa un got amb un forat massa estret per a 6 llapis.|En el proyecto libre, hace un vaso con un agujero demasiado estrecho para 6 lápices.", "Perquè hi càpiguen 6 llapis al voltant d'un, el forat ha de fer almenys tres llapis d'ample: uns 27 mm o més.|Para que quepan 6 lápices alrededor de uno, el agujero tiene que medir al menos tres lápices de ancho: unos 27 mm o más."]],
    diff: { mes: "Afegir-hi la safata de la goma, gravar-hi el número de la taula o fer un porta-llapis hexagonal amb 7 forats (6 al voltant d'1).|Añadirle la bandeja de la goma, grabarle el número de la mesa o hacer un portalápices hexagonal con 7 agujeros (6 alrededor de 1).",
      menys: "Partir del porta-llapis dels sis forats i personalitzar-lo (color, forma de fora, una estrella en relleu). Deixar escrites a la pissarra les posicions dels sis forats.|Partir del portalápices de los seis agujeros y personalizarlo (color, forma de fuera, una estrella en relieve). Dejar escritas en la pizarra las posiciones de los seis agujeros." },
    aval: { ticket: ['Per què el forat fa 9 mm si el llapis en fa 8?|¿Por qué el agujero mide 9 mm si el lápiz mide 8?', 'Dos forats de 9 mm a 12 mm de centre a centre: quant fa la paret?|Dos agujeros de 9 mm a 12 mm de centro a centro: ¿cuánto mide la pared?'],
      rubric: [['Mides reals|Medidas reales', 'Mesura el llapis i tria el forat amb marge, i ho explica.|Mide el lápiz y elige el agujero con margen, y lo explica.', 'Fa servir les mides donades sense relacionar-les amb el llapis.|Usa las medidas dadas sin relacionarlas con el lápiz.'],
        ['Fons i parets|Fondo y paredes', "Calcula i deixa fons i parets de 2 mm o més.|Calcula y deja fondo y paredes de 2 mm o más.", 'Ho arregla quan la comprovació avisa.|Lo arregla cuando la comprobación avisa.'],
        ['Projecte complet|Proyecto completo', "Porta-llapis propi per a 6 llapis, llest per imprimir i amb l'STL descarregat.|Portalápices propio para 6 lápices, listo para imprimir y con el STL descargado.", "Falta algun requisit o no està pensat per a 6 llapis.|Falta algún requisito o no está pensado para 6 lápices."]] },
    casa: "Mesureu objectes de casa que es guarden en un recipient (retoladors, pinzells, raspalls de dents) i penseu quina mida de forat necessitaria cadascun. Dibuixeu-ne un organitzador.|Medid objetos de casa que se guardan en un recipiente (rotuladores, pinceles, cepillos de dientes) y pensad qué tamaño de agujero necesitaría cada uno. Dibujad un organizador.",
    intro: "Projecte de la unitat i gran moment de la Nuvi: el porta-llapis reuneix el que han après a les unitats 5 i 6 (forats, fons i parets, base plana, mida real, STL) i hi afegeix una idea molt important de disseny: partir de les mides reals d'un objecte i deixar-hi marge. Deixeu temps per al projecte i per a la galeria.|Proyecto de la unidad y gran momento de Nuvi: el portalápices reúne lo que han aprendido en las unidades 5 y 6 (agujeros, fondo y paredes, base plana, tamaño real, STL) y añade una idea muy importante de diseño: partir de las medidas reales de un objeto y dejar margen. Dejad tiempo para el proyecto y para la galería.",
    claus: ["Primer es mesura l'objecte real: un llapis fa uns 8 mm de punta a punta.|Primero se mide el objeto real: un lápiz mide unos 8 mm de punta a punta.", "El forat es fa una mica més gran (9 mm) perquè hi entri i en surti fàcilment.|El agujero se hace un poco más grande (9 mm) para que entre y salga fácilmente.",
      "Paret entre forats = distància entre centres − diàmetre: 12 − 9 = 3 mm.|Pared entre agujeros = distancia entre centros − diámetro: 12 − 9 = 3 mm.", "Fons de 2 mm: els forats comencen a z = 2.|Fondo de 2 mm: los agujeros empiezan en z = 2."],
    prev: ['Haver fet les tres sessions anteriors de la unitat (capes, revisió i STL).|Haber hecho las tres sesiones anteriores de la unidad (capas, revisión y STL).', 'Saber fer forats que no travessen i duplicar-los (unitats 4 i 5).|Saber hacer agujeros que no atraviesan y duplicarlos (unidades 4 y 5).', 'Saber mesurar amb el regle en mil·límetres.|Saber medir con la regla en milímetros.'],
    faq: [["Quant tarda d'imprimir un porta-llapis com aquest?|¿Cuánto tarda en imprimirse un portalápices como este?", "Fa 40 mm d'alt (200 capes): segons la impressora i com s'ompli per dins, unes quantes hores. El laminador ho calcula abans de començar; si cal, es pot fer més baix o més buit.|Mide 40 mm de alto (200 capas): según la impresora y cómo se rellene por dentro, unas cuantas horas. El laminador lo calcula antes de empezar; si hace falta, se puede hacer más bajo o más hueco."],
      ["I si els llapis de la classe són més gruixuts?|¿Y si los lápices de la clase son más gruesos?", "Cal mesurar-los i fer el forat 1 mm més gran que la mida de punta a punta. Els de colors gruixuts poden fer 10 mm o més: forats d'11 mm i forats més separats perquè la paret continuï fent 2 mm.|Hay que medirlos y hacer el agujero 1 mm más grande que la medida de punta a punta. Los de colores gruesos pueden medir 10 mm o más: agujeros de 11 mm y agujeros más separados para que la pared siga midiendo 2 mm."],
      ["Per què no es comprova sol que hi càpiguen 6 llapis?|¿Por qué no se comprueba solo que quepan 6 lápices?", "El taller comprova si el model es pot imprimir, però no sap per a què serveix. Per això és un criteri que revisen ells mateixos (i el company): és part de pensar com a dissenyadors.|El taller comprueba si el modelo se puede imprimir, pero no sabe para qué sirve. Por eso es un criterio que revisan ellos mismos (y el compañero): es parte de pensar como diseñadores."]],
    tec: [["Després de duplicar, la còpia surt molt lluny.|Después de duplicar, la copia sale muy lejos.", "La còpia surt al costat; escriviu-ne la x a Posició. Si després torneu a duplicar, la nova còpia fa el mateix salt i ja surt al seu lloc (x = 12).|La copia sale al lado; escribid su x en Posición. Si después volvéis a duplicar, la nueva copia da el mismo salto y ya sale en su sitio (x = 12)."],
      ["No puc seleccionar els tres forats alhora.|No puedo seleccionar los tres agujeros a la vez.", "Toqueu un forat, després «Més peces» i els altres dos. L'inspector ha de dir «3 peces».|Tocad un agujero, después «Más piezas» y los otros dos. El inspector tiene que decir «3 piezas»."],
      ["El porta-llapis va lent amb tants forats.|El portalápices va lento con tantos agujeros.", "És normal: calcular forats costa una mica. Treballeu en mode d'edició i mireu el Resultat només per comprovar.|Es normal: calcular agujeros cuesta un poco. Trabajad en modo de edición y mirad el Resultado solo para comprobar."]],
    extra: ["Imprimir 2 o 3 porta-llapis i fer la prova de veritat amb els llapis de la classe (fitxa).|Imprimir 2 o 3 portalápices y hacer la prueba de verdad con los lápices de la clase (ficha).", "Fer una enquesta a la classe de 3r: què més voldrien al porta-llapis (lloc per a la goma, per a les tisores…).|Hacer una encuesta en la clase de 3.º: qué más querrían en el portalápices (sitio para la goma, para las tijeras…).", 'Calcular quant de plàstic estalvia un porta-llapis amb forats respecte d\'un bloc massís.|Calcular cuánto plástico ahorra un portalápices con agujeros respecto a un bloque macizo.'],
    trans: ['Unitat següent: dissenyar per a persones (qui ho farà servir i què necessita).|Unidad siguiente: diseñar para personas (quién lo usará y qué necesita).', 'Matemàtiques: mesurar i comparar longituds; la diferència com a resta.|Matemáticas: medir y comparar longitudes; la diferencia como resta.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Projecte: el porta-llapis|Proyecto: el portalápices', x: 'Sis llapis per a cada taula de la classe de 3r|Seis lápices para cada mesa de la clase de 3.º', nota: "Presenta el projecte i la gran impressió de la Nuvi.|Presenta el proyecto y la gran impresión de Nuvi." },
      { id: 's2', k: 'pregunta', t: 'Què ha de tenir un bon porta-llapis?|¿Qué tiene que tener un buen portalápices?', x: 'Pensa en els llapis, en la taula i en la Nuvi.|Piensa en los lápices, en la mesa y en Nuvi.', nota: 'Feu la llista de requisits a la pissarra: la fareu servir al final.|Haced la lista de requisitos en la pizarra: la usaréis al final.' },
      { id: 's3', k: 'anim', t: 'Mesura el llapis|Mide el lápiz', anim: 'm6llapis', x: '7 mm de cara a cara, 8 de punta a punta, forat de 9.|7 mm de cara a cara, 8 de punta a punta, agujero de 9.', nota: "Que mesurin el seu llapis mentre ho expliques.|Que midan su lápiz mientras lo explicas." },
      { id: 's4', k: 'media', t: 'Fons i parets|Fondo y paredes', x: 'Fons de 2 mm i parets de 3 mm entre forats.|Fondo de 2 mm y paredes de 3 mm entre agujeros.', media: { k: 'model', model: TALL, view: 'front', spin: false }, nota: 'Vist de davant: es veu el fons de 2 mm sota cada forat.|Visto de frente: se ve el fondo de 2 mm bajo cada agujero.' },
      { id: 's5', k: 'anim', t: 'Sis llapis|Seis lápices', anim: 'm6sis', x: "Dues files de tres o un got: 6 al voltant d'1.|Dos filas de tres o un vaso: 6 alrededor de 1.", nota: "Deixa que triïn la manera al projecte.|Deja que elijan la manera en el proyecto." },
      { id: 's6', k: 'media', t: 'La prova dels llapis|La prueba de los lápices', x: 'Hi caben els 6 i queden drets.|Caben los 6 y quedan de pie.', media: { k: 'model', model: AMB_LLAPIS }, nota: "Pregunta què passaria si el porta-llapis fos de 10 mm d'alt.|Pregunta qué pasaría si el portalápices fuera de 10 mm de alto." },
      { id: 's7', k: 'concepte', t: 'Calcular la paret|Calcular la pared', x: 'Paret = distància entre centres − diàmetre. 12 − 9 = 3 mm.|Pared = distancia entre centros − diámetro. 12 − 9 = 3 mm.', nota: 'Feu-ne un altre exemple: forats d\'11 a 14 mm de distància.|Haced otro ejemplo: agujeros de 11 a 14 mm de distancia.' },
      { id: 's8', k: 'activitat', t: 'Mesura el teu llapis|Mide tu lápiz', timer: 7, punts: ['Cara a cara, punta a punta i llargada.|Cara a cara, punta a punta y largo.', 'Dibuix des de dalt a mida real.|Dibujo desde arriba a tamaño real.', 'Compara amb un company.|Compara con un compañero.'], nota: 'Compàs obert a 4,5 mm per als forats.|Compás abierto a 4,5 mm para los agujeros.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['El primer forat (z = 2).|El primer agujero (z = 2).', 'Els sis forats.|Los seis agujeros.', 'El porta-llapis sense fons.|El portalápices sin fondo.'], nota: 'La safata de la goma és un repte extra.|La bandeja de la goma es un reto extra.' },
      { id: 's10', k: 'media', t: 'Els sis forats|Los seis agujeros', x: 'x = −12, 0, 12 · y = −6, 6.|x = −12, 0, 12 · y = −6, 6.', media: { k: 'model', model: PORTA, view: 'top' }, nota: "Ajuda per a qui s'encalli al repte dels sis forats.|Ayuda para quien se atasque en el reto de los seis agujeros." },
      { id: 's11', k: 'repte', t: 'El porta-llapis de la taula|El portalápices de la mesa', punts: ['Hi caben 6 llapis.|Caben 6 lápices.', 'Fons i parets de 2 mm o més.|Fondo y paredes de 2 mm o más.', 'Base plana, una peça, STL.|Base plana, una pieza, STL.'], nota: 'Projecte de la unitat: es desa al portafoli.|Proyecto de la unidad: se guarda en el portafolio.' },
      { id: 's12', k: 'concepte', t: 'Revisa abans de desar|Revisa antes de guardar', x: "Repassa la llista de requisits de la pissarra i la revisió de la Nuvi. Un company l'ha de mirar de costat.|Repasa la lista de requisitos de la pizarra y la revisión de Nuvi. Un compañero lo tiene que mirar de lado.", nota: 'Revisió entre iguals breu abans de desar.|Revisión entre iguales breve antes de guardar.' },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Mesurar el real i deixar marge.|Medir lo real y dejar margen.', 'Paret = centres − diàmetre.|Pared = centros − diámetro.', 'Llest per imprimir, i a l\'STL!|Listo para imprimir, ¡y al STL!'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Per què 9 mm si el llapis en fa 8?|¿Por qué 9 mm si el lápiz mide 8?', 'Paret entre forats de 9 a 12 mm?|¿Pared entre agujeros de 9 a 12 mm?'], nota: 'Oral, durant la galeria.|Oral, durante la galería.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: 'Mesura objectes de casa i pensa quin forat necessiten.|Mide objetos de casa y piensa qué agujero necesitan.', nota: 'Bona preparació per a la unitat 7.|Buena preparación para la unidad 7.' }
    ],
    print: [
      { id: 'p1', t: 'Fitxa: el meu porta-llapis|Ficha: mi portalápices', k: 'fitxa', intro: "Planifica el porta-llapis abans de fer-lo a l'ordinador.|Planifica el portalápices antes de hacerlo en el ordenador.",
        items: [{ q: 'El meu llapis fa ____ mm de cara a cara i ____ mm de punta a punta.|Mi lápiz mide ____ mm de cara a cara y ____ mm de punta a punta.', sol: 'Uns 7 i 8 mm (un llapis normal).|Unos 7 y 8 mm (un lápiz normal).' },
          { q: 'El forat farà ____ mm (punta a punta + marge).|El agujero medirá ____ mm (punta a punta + margen).', sol: '9 mm per a un llapis normal.|9 mm para un lápiz normal.' },
          { q: 'Dibuixa el porta-llapis des de dalt: on van els 6 llapis?|Dibuja el portalápices desde arriba: ¿dónde van los 6 lápices?', sol: "Dibuix lliure: dues files de tres, un got o una altra idea.|Dibujo libre: dos filas de tres, un vaso u otra idea." },
          { q: 'Forats a ____ mm de centre a centre → paret de ____ mm. Fons de ____ mm.|Agujeros a ____ mm de centro a centro → pared de ____ mm. Fondo de ____ mm.', sol: '12 mm → 12 − 9 = 3 mm de paret. Fons de 2 mm.|12 mm → 12 − 9 = 3 mm de pared. Fondo de 2 mm.' }] },
      { id: 'p2', t: 'Fitxa: la prova de veritat|Ficha: la prueba de verdad', k: 'fitxa', intro: "Si heu imprès el porta-llapis, proveu-lo amb llapis de veritat.|Si habéis impreso el portalápices, probadlo con lápices de verdad.",
        items: [{ q: 'Hi caben els 6 llapis? Entren i surten bé?|¿Caben los 6 lápices? ¿Entran y salen bien?', sol: 'Resposta oberta.|Respuesta abierta.' },
          { q: "S'aguanta dret amb els 6 llapis? Es tomba si el toques?|¿Se aguanta de pie con los 6 lápices? ¿Se vuelca si lo tocas?", sol: 'Resposta oberta.|Respuesta abierta.' },
          { q: 'Què canviaries a la versió 2?|¿Qué cambiarías en la versión 2?', sol: "Per exemple: forats més grans per als llapis de colors, més alt, una safata.|Por ejemplo: agujeros más grandes para los lápices de colores, más alto, una bandeja." }] }
    ]
  }
  };
})());
/* ---------- Sessió 5 · Taller: de Numi a la impressora (m6-5) ----------
   La sessió pont: de l'STL de Numi a una impressora de veritat. Es pot fer sense impressora i sense internet (laminador de
   paper, llista i preguntes); amb impressora, el/la docent fa la demostració al laminador i imprimeix les fitxes. */
Object.assign(TGUIDE, (() => {
  const P = (id, t, s, p, c, o = {}) => ({ id, t, s, p, r: o.r || [0, 0, 0], c, ...o });
  const B = (id, t, s, x, y, z0, c, o = {}) => P(id, t, s, [x, y, z0 + s[2] / 2], c, o);
  const FITXA = { parts: [B('fitxa', 'cyl', [32, 32, 3], 0, 0, 0, '#F5893A'), B('ini', 'text', [18.24, 12, 2], 0, 0, 3, '#FFFFFF', { txt: 'AB' })] };
  const TDRETA = { parts: [B('pal', 'box', [6, 6, 30], 0, 0, 0, '#3D7BF4'), B('barra', 'box', [30, 6, 6], 0, 0, 30, '#3D7BF4')] };
  return {
  'm6-5': {
    obj: ["L'alumne/a descriu el camí d'un disseny: STL de Numi, (Tinkercad, opcional), laminador i impressora.|El alumno/a describe el camino de un diseño: STL de Numi, (Tinkercad, opcional), laminador e impresora.",
      "L'alumne/a coneix els paràmetres bàsics del laminador: capes de 0,2 mm, farciment del 15-20 % i suports només si cal.|El alumno/a conoce los parámetros básicos del laminador: capas de 0,2 mm, relleno del 15-20 % y soportes solo si hace falta.",
      "L'alumne/a revisa un model amb la llista abans d'imprimir i el corregeix (Alinea → A terra, Proporcional).|El alumno/a revisa un modelo con la lista antes de imprimir y lo corrige (Alinea → Al suelo, Proporcional).",
      "L'alumne/a prepara una peça petita i ràpida (la fitxa de les inicials) per imprimir-la.|El alumno/a prepara una pieza pequeña y rápida (la ficha de las iniciales) para imprimirla."],
    comp: ['Tecnologia i digitalització: fabricació digital; del model CAD a la peça impresa (STL, laminador, impressora)|Tecnología y digitalización: fabricación digital; del modelo CAD a la pieza impresa (STL, laminador, impresora)', 'Matemàtiques, sentit de la mesura: capes (× 5), percentatges (15-20 %) i escales|Matemáticas, sentido de la medida: capas (× 5), porcentajes (15-20 %) y escalas',
      "Pensament computacional: seqüenciar un procés i revisar-lo amb una llista de comprovació|Pensamiento computacional: secuenciar un proceso y revisarlo con una lista de comprobación", 'Seguretat i ús responsable de les màquines: temperatures i supervisió d\'un adult|Seguridad y uso responsable de las máquinas: temperaturas y supervisión de un adulto'],
    vocab: [['Laminador|Laminador', "Programa que talla el model en capes i en fa les ordres per a la impressora (en anglès, slicer).|Programa que corta el modelo en capas y hace sus órdenes para la impresora (en inglés, slicer)."], ['Farciment|Relleno', "La quadrícula de dins de la peça; un 15-20 % vol dir que només s'omple una part.|La cuadrícula de dentro de la pieza; un 15-20 % quiere decir que solo se llena una parte."],
      ['Suports|Soportes', "Columnes de plàstic que aguanten els voladissos de més de 45° i després es treuen.|Columnas de plástico que aguantan los voladizos de más de 45° y después se quitan."], ['G-code|G-code', "El fitxer d'ordres que fa el laminador: per on es mou el broquet, capa a capa.|El archivo de órdenes que hace el laminador: por dónde se mueve la boquilla, capa a capa."],
      ['Importar|Importar', "Portar un fitxer a dins d'un programa (al Tinkercad, el botó Importa).|Llevar un archivo dentro de un programa (en Tinkercad, el botón Importar)."], ['Llista de comprovació|Lista de comprobación', 'Preguntes que es revisen sempre abans de fer una cosa.|Preguntas que se revisan siempre antes de hacer una cosa.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Taller: de Numi a la impressora»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Taller: de Numi a la impresora»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Paper quadriculat, colors i les targetes de la llista. Si en teniu: l'ordinador del docent amb un laminador instal·lat i una impressora 3D amb PLA|Papel cuadriculado, colores y las tarjetas de la lista. Si tenéis: el ordenador del docente con un laminador instalado y una impresora 3D con PLA"],
      imprimir: ['Fitxa: preparo la impressió|Ficha: preparo la impresión', "Targetes: la llista abans d'imprimir|Tarjetas: la lista antes de imprimir"],
      prep: ["Laminador: instal·leu-ne un de gratuït a l'ordinador del docent (Ultimaker Cura o PrusaSlicer) o el que recomani el fabricant de la vostra impressora, i configureu-hi el perfil de la impressora i el filament PLA. Funciona sense internet un cop instal·lat.|Laminador: instalad uno gratuito en el ordenador del docente (Ultimaker Cura o PrusaSlicer) o el que recomiende el fabricante de vuestra impresora, y configurad el perfil de la impresora y el filamento PLA. Funciona sin internet una vez instalado.",
        "Tinkercad (opcional, necessita internet): és un taller 3D gratuït d'Autodesk al navegador. Amb alumnat de menys de 14 anys, feu servir les classes que gestiona el docent: el/la docent crea la classe i l'alumnat hi entra amb el codi de classe i un àlies, sense comptes personals. «Importa» hi obre els fitxers STL.|Tinkercad (opcional, necesita internet): es un taller 3D gratuito de Autodesk en el navegador. Con alumnado de menos de 14 años, usad las clases que gestiona el docente: el/la docente crea la clase y el alumnado entra con el código de clase y un alias, sin cuentas personales. «Importar» abre allí los archivos STL.",
        "Imprimiu abans una fitxa de prova (32 mm, capes de 0,2 mm, farciment del 15-20 %, sense suports) per saber quant tarda la vostra impressora i ensenyar-la a classe.|Imprimid antes una ficha de prueba (32 mm, capas de 0,2 mm, relleno del 15-20 %, sin soportes) para saber cuánto tarda vuestra impresora y enseñarla en clase."] },
    plan: [
      { min: 5, t: "La impressora de l'escola|La impresora de la escuela", fase: 'inici', fa: "Presenta l'encàrrec de la mestra Aina. Si teniu impressora, ensenyeu-la apagada i la fitxa de prova; si no, una peça impresa o una foto. Pregunta: què cal fer perquè un disseny de la pantalla arribi a la impressora?|Presenta el encargo de la maestra Aina. Si tenéis impresora, enseñadla apagada y la ficha de prueba; si no, una pieza impresa o una foto. Pregunta: ¿qué hay que hacer para que un diseño de la pantalla llegue a la impresora?",
        diu: ["La impressora entén els models de Numi directament?|¿La impresora entiende los modelos de Numi directamente?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'El camí, el laminador i la llista|El camino, el laminador y la lista', fase: 'teoria', fa: "Explica el camí (STL → Tinkercad opcional → laminador → impressora), els tres paràmetres del laminador (capa de 0,2 mm, farciment del 15-20 %, suports només si cal) i la llista de sis preguntes. Recalca la seguretat: el broquet arriba a uns 200 °C.|Explica el camino (STL → Tinkercad opcional → laminador → impresora), los tres parámetros del laminador (capa de 0,2 mm, relleno del 15-20 %, soportes solo si hace falta) y la lista de seis preguntas. Recalca la seguridad: la boquilla llega a unos 200 °C.",
        diu: ['Per què no omplim la peça al 100 %?|¿Por qué no llenamos la pieza al 100 %?', 'Quan calen suports?|¿Cuándo hacen falta soportes?'], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 9, t: 'Fes de laminador|Haz de laminador', fase: 'desconnectat', fa: "Per parelles «laminen» la fitxa en paper: calculen les capes (25), dibuixen la capa 5 (cercle amb farciment en quadrícula) i la capa 20 (només les lletres). Es pot fer sense ordinador ni internet.|Por parejas «laminan» la ficha en papel: calculan las capas (25), dibujan la capa 5 (círculo con relleno en cuadrícula) y la capa 20 (solo las letras). Se puede hacer sin ordenador ni internet.",
        diu: ['Per què a la capa 20 només hi ha les lletres?|¿Por qué en la capa 20 solo están las letras?'], slides: ['s7'], app: 'Encara no: paper i colors.|Todavía no: papel y colores.', org: 'Per parelles|Por parejas' },
      { min: 18, t: 'La fitxa, la llista i els errors|La ficha, la lista y los errores', fase: 'ordinador', fa: "Fan la sessió a l'app: capes de la fitxa, la T que necessita suports, l'ordre del camí, la fitxa amb les inicials (Text de 2 mm a z = 3) i la fitxa que flota (Alinea → A terra). El posagots massa gran és un repte extra. Fan la seva fitxa i en descarreguen l'STL.|Hacen la sesión en la app: capas de la ficha, la T que necesita soportes, el orden del camino, la ficha con las iniciales (Texto de 2 mm en z = 3) y la ficha que flota (Alinea → Al suelo). El posavasos demasiado grande es un reto extra. Hacen su ficha y descargan su STL.",
        diu: ["La teva fitxa passa les sis preguntes de la llista?|¿Tu ficha pasa las seis preguntas de la lista?"], slides: ['s8', 's9', 's10', 's11'], app: 'Sessió «Taller: de Numi a la impressora», fins a «La teva fitxa per imprimir».|Sesión «Taller: de Numi a la impresora», hasta «Tu ficha para imprimir».', org: 'Individual|Individual' },
      { min: 14, t: 'Al laminador (demostració)|En el laminador (demostración)', fase: 'crea', fa: "Amb el projector, obre l'STL d'una fitxa al laminador: col·loca-la al mig de la placa, tria capa de 0,2 mm, farciment del 15-20 % i sense suports, i lamina-la. Llegiu junts el temps i el filament i apunteu-los a la fitxa. Si teniu temps i internet, ensenyeu com s'importa l'STL al Tinkercad. Si teniu impressora, envieu-hi les fitxes (una o dues per sessió) i imprimiu-les a la tarda.|Con el proyector, abre el STL de una ficha en el laminador: colócala en el centro de la placa, elige capa de 0,2 mm, relleno del 15-20 % y sin soportes, y lamínala. Leed juntos el tiempo y el filamento y apuntadlos en la ficha. Si tenéis tiempo e internet, enseñad cómo se importa el STL en Tinkercad. Si tenéis impresora, enviad las fichas (una o dos por sesión) e imprimidlas por la tarde.",
        diu: ['Quant tardarà la fitxa? I si la féssim el doble d\'alta?|¿Cuánto tardará la ficha? ¿Y si la hiciéramos el doble de alta?'], slides: ['s12', 's13'], app: 'Pas «A la impressora de veritat».|Paso «A la impresora de verdad».', org: 'Tot el grup|Todo el grupo' },
      { min: 6, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa el camí, els tres paràmetres i la llista. Tiquet de sortida.|Repasa el camino, los tres parámetros y la lista. Ticket de salida.",
        diu: ["Explica a un company el camí de la teva fitxa en quatre passos.|Explica a un compañero el camino de tu ficha en cuatro pasos."], slides: ['s14', 's15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Al repte de la fitxa que flota tria «Cada peça a terra» i les inicials queden enfonsades dins del disc.|En el reto de la ficha que flota elige «Cada pieza al suelo» y las iniciales quedan hundidas dentro del disco.", "Desfés i tria «A terra (z = 0)»: baixen totes dues juntes, sense desfer l'apilament.|Deshaz y elige «Al suelo (z = 0)»: bajan las dos juntas, sin deshacer el apilamiento."],
      ["Deixa el text amb el gruix de la paleta (3 mm) i la comprovació de 5 mm no es marca.|Deja el texto con el grosor de la paleta (3 mm) y la comprobación de 5 mm no se marca.", "A Mida, la z del text és el gruix del relleu: 2 mm.|En Medida, la z del texto es el grosor del relieve: 2 mm."],
      ["Creu que com més farciment, millor, i vol posar-hi un 100 %.|Cree que cuanto más relleno, mejor, y quiere poner un 100 %.", "Per a una fitxa, un 15-20 % ja és fort: més farciment gasta més plàstic i temps sense gaire diferència.|Para una ficha, un 15-20 % ya es fuerte: más relleno gasta más plástico y tiempo sin mucha diferencia."],
      ["Confon el fitxer STL amb el fitxer que va a la impressora.|Confunde el archivo STL con el archivo que va a la impresora.", "L'STL és la forma; el laminador en fa el fitxer d'ordres (G-code), capa a capa. Recordeu el «laminador de paper».|El STL es la forma; el laminador hace el archivo de órdenes (G-code), capa a capa. Recordad el «laminador de papel»."]],
    diff: { mes: "Comparar al laminador la mateixa fitxa amb capes de 0,1 i 0,3 mm i amb farciments diferents: com canvien el temps i el filament? Importar l'STL al Tinkercad i afegir-hi un forat per fer-ne un clauer.|Comparar en el laminador la misma ficha con capas de 0,1 y 0,3 mm y con rellenos distintos: ¿cómo cambian el tiempo y el filamento? Importar el STL en Tinkercad y añadirle un agujero para hacer un llavero.",
      menys: "Fer el «laminador de paper» tots junts a la pissarra i, a l'app, fer només la fitxa amb les inicials i la llista.|Hacer el «laminador de papel» todos juntos en la pizarra y, en la app, hacer solo la ficha con las iniciales y la lista." },
    aval: { ticket: ['Digues tres coses que tries al laminador.|Di tres cosas que eliges en el laminador.', "Digues dues preguntes de la llista abans d'imprimir.|Di dos preguntas de la lista antes de imprimir."],
      rubric: [['El camí del fitxer|El camino del archivo', "Explica l'ordre: STL, laminador, impressora (i el Tinkercad com a opció).|Explica el orden: STL, laminador, impresora (y Tinkercad como opción).", "Coneix les parts però en barreja l'ordre.|Conoce las partes pero mezcla el orden."],
        ['El laminador|El laminador', 'Tria capa de 0,2 mm, farciment del 15-20 % i decideix si calen suports.|Elige capa de 0,2 mm, relleno del 15-20 % y decide si hacen falta soportes.', 'Sap què és el laminador, però no en tria bé els paràmetres.|Sabe qué es el laminador, pero no elige bien sus parámetros.'],
        ["La llista abans d'imprimir|La lista antes de imprimir", 'Revisa les sis preguntes i corregeix el que falla.|Revisa las seis preguntas y corrige lo que falla.', 'Revisa només algunes preguntes.|Revisa solo algunas preguntas.']] },
    casa: "Expliqueu a casa el camí d'un disseny fins a la impressora. Si teniu ordinador, podeu instal·lar un laminador gratuït i obrir-hi l'STL de la fitxa (des de «Projectes») per veure'n les capes i el temps.|Explicad en casa el camino de un diseño hasta la impresora. Si tenéis ordenador, podéis instalar un laminador gratuito y abrir el STL de la ficha (desde «Proyectos») para ver sus capas y el tiempo.",
    intro: "Sessió pont entre el taller de Numi i una impressora de veritat. Explica el que passa després de descarregar l'STL: el Tinkercad com a opció per continuar el disseny, el laminador (capes, farciment, suports, temps i filament) i la llista de revisió. Està pensada perquè funcioni sense impressora i sense internet (laminador de paper, llista i preguntes) i, si l'escola té impressora, per acabar imprimint la fitxa de cada alumne/a.|Sesión puente entre el taller de Numi y una impresora de verdad. Explica lo que pasa después de descargar el STL: Tinkercad como opción para continuar el diseño, el laminador (capas, relleno, soportes, tiempo y filamento) y la lista de revisión. Está pensada para que funcione sin impresora y sin internet (laminador de papel, lista y preguntas) y, si la escuela tiene impresora, para acabar imprimiendo la ficha de cada alumno/a.",
    claus: ["Camí: STL de Numi → (Tinkercad, «Importa», opcional) → laminador → impressora.|Camino: STL de Numi → (Tinkercad, «Importar», opcional) → laminador → impresora.", 'Laminador: capa de 0,2 mm, farciment del 15-20 %, suports només amb voladissos de més de 45°.|Laminador: capa de 0,2 mm, relleno del 15-20 %, soportes solo con voladizos de más de 45°.',
      "El laminador calcula el temps i el filament abans d'imprimir.|El laminador calcula el tiempo y el filamento antes de imprimir.", "La llista: placa, base plana, una sola peça, parets d'1,2-2 mm o més, que hi càpiga, voladissos ≤ 45°.|La lista: placa, base plana, una sola pieza, paredes de 1,2-2 mm o más, que quepa, voladizos ≤ 45°."],
    prev: ["Haver fet «Exportar el fitxer STL» (sessió 3).|Haber hecho «Exportar el archivo STL» (sesión 3).", 'Saber les regles de la sessió «Gruix i base plana».|Saber las reglas de la sesión «Grosor y base plana».', 'Saber fer servir la forma Text (unitat 5).|Saber usar la forma Texto (unidad 5).'],
    faq: [["Cal internet per fer la sessió?|¿Hace falta internet para hacer la sesión?", "Numi s'ha de poder obrir, però el laminador és un programa de l'ordinador i funciona sense internet un cop instal·lat. El Tinkercad sí que necessita internet: és opcional.|Numi se tiene que poder abrir, pero el laminador es un programa del ordenador y funciona sin internet una vez instalado. Tinkercad sí necesita internet: es opcional."],
      ["I si l'escola no té impressora?|¿Y si la escuela no tiene impresora?", "La sessió funciona igual: es lamina en paper, es revisa la llista i, si hi ha un laminador instal·lat, es pot laminar la fitxa i llegir-ne el temps i el filament sense imprimir-la. També podeu demanar a un espai maker o a una biblioteca propera si imprimeixen per a escoles.|La sesión funciona igual: se lamina en papel, se revisa la lista y, si hay un laminador instalado, se puede laminar la ficha y leer su tiempo y filamento sin imprimirla. También podéis preguntar a un espacio maker o a una biblioteca cercana si imprimen para escuelas."],
      ['Per què fem servir el Tinkercad si ja tenim Numi?|¿Por qué usamos Tinkercad si ya tenemos Numi?', "No cal: el laminador obre directament l'STL de Numi. El Tinkercad és una opció per a qui vulgui continuar el disseny en una eina que es fa servir a moltes escoles i instituts.|No hace falta: el laminador abre directamente el STL de Numi. Tinkercad es una opción para quien quiera continuar el diseño en una herramienta que se usa en muchas escuelas e institutos."],
      ['És segur imprimir a classe?|¿Es seguro imprimir en clase?', "Sí, amb un adult i en un lloc ventilat. El broquet arriba a uns 200 °C i la placa, si s'escalfa, a uns 60 °C: no es toquen mentre la impressora treballa ni just després.|Sí, con un adulto y en un lugar ventilado. La boquilla llega a unos 200 °C y la placa, si se calienta, a unos 60 °C: no se tocan mientras la impresora trabaja ni justo después."]],
    tec: [["Al laminador, la fitxa surt minúscula o gegant.|En el laminador, la ficha sale minúscula o gigante.", "L'STL de Numi és en mil·límetres. Si el programa pregunta les unitats en obrir-lo, trieu mil·límetres i comproveu que fa 32 mm.|El STL de Numi está en milímetros. Si el programa pregunta las unidades al abrirlo, elegid milímetros y comprobad que mide 32 mm."],
      ["Al Tinkercad, el model importat és una sola peça.|En Tinkercad, el modelo importado es una sola pieza.", "És normal: l'STL només guarda la forma. Es pot moure, escalar i combinar amb altres formes o forats, però no se'n separen les peces originals.|Es normal: el STL solo guarda la forma. Se puede mover, escalar y combinar con otras formas o agujeros, pero no se separan sus piezas originales."],
      ["La primera capa no s'enganxa a la placa.|La primera capa no se pega a la placa.", "Netegeu la placa, comproveu que està anivellada (segons el manual) i, en peces petites, activeu una vora d'adherència (brim) al laminador.|Limpiad la placa, comprobad que está nivelada (según el manual) y, en piezas pequeñas, activad un borde de adherencia (brim) en el laminador."],
      ['On és l\'STL de la fitxa?|¿Dónde está el STL de la ficha?', "Al projecte (botó STL de la barra de baix) o a «Projectes», un cop desada. Es descarrega a la carpeta de baixades del navegador.|En el proyecto (botón STL de la barra de abajo) o en «Proyectos», una vez guardada. Se descarga en la carpeta de descargas del navegador."]],
    extra: ["Fer un «racó de la impressora» a la classe amb la llista penjada i un registre de les impressions (nom, temps i filament).|Hacer un «rincón de la impresora» en la clase con la lista colgada y un registro de las impresiones (nombre, tiempo y filamento).", "Comparar el temps que dona el laminador amb el temps real d'impressió.|Comparar el tiempo que da el laminador con el tiempo real de impresión.", 'Fer les fitxes de tota la classe amb un mateix disseny i inicials diferents.|Hacer las fichas de toda la clase con un mismo diseño e iniciales distintas.'],
    trans: ['Unitat següent: dissenyar per a persones (i un altre taller: el tallagaletes).|Unidad siguiente: diseñar para personas (y otro taller: el cortador de galletas).', 'Matemàtiques: els percentatges (15-20 %).|Matemáticas: los porcentajes (15-20 %).'],
    slides: [
      { id: 's1', k: 'portada', t: 'Taller: de Numi a la impressora|Taller: de Numi a la impresora', x: 'El camí sencer, del disseny a la peça|El camino entero, del diseño a la pieza', nota: "Presenta l'encàrrec de la mestra Aina i, si en teniu, la impressora apagada.|Presenta el encargo de la maestra Aina y, si tenéis, la impresora apagada." },
      { id: 's2', k: 'pregunta', t: 'Com arriba un disseny a la impressora?|¿Cómo llega un diseño a la impresora?', x: 'Pista: la impressora no entén els models de Numi.|Pista: la impresora no entiende los modelos de Numi.', nota: 'Recull idees i deixa-les a la pissarra.|Recoge ideas y déjalas en la pizarra.' },
      { id: 's3', k: 'anim', t: 'El camí del fitxer|El camino del archivo', anim: 'm65cami', x: 'Numi → STL → laminador → impressora (i el Tinkercad, si vols).|Numi → STL → laminador → impresora (y Tinkercad, si quieres).', nota: "El Tinkercad és opcional: el laminador obre l'STL directament.|Tinkercad es opcional: el laminador abre el STL directamente." },
      { id: 's4', k: 'anim', t: 'El laminador|El laminador', anim: 'm65lamina', x: 'Capa de 0,2 mm · farciment del 15-20 % · suports si cal.|Capa de 0,2 mm · relleno del 15-20 % · soportes si hace falta.', nota: "Si teniu el laminador obert, ensenyeu-ho en directe.|Si tenéis el laminador abierto, enseñadlo en directo." },
      { id: 's5', k: 'anim', t: "La llista abans d'imprimir|La lista antes de imprimir", anim: 'm65llista', x: 'Sis preguntes, sis «sí».|Seis preguntas, seis «sí».', nota: "Pengeu les targetes de la llista al costat de la impressora.|Colgad las tarjetas de la lista al lado de la impresora." },
      { id: 's6', k: 'concepte', t: 'El Tinkercad|Tinkercad', x: "Taller 3D gratuït al web (d'Autodesk). «Importa» hi obre l'STL. A l'escola, amb la classe del docent (codi i àlies).|Taller 3D gratuito en la web (de Autodesk). «Importar» abre allí el STL. En la escuela, con la clase del docente (código y alias).", nota: "Amb menors de 14 anys, només amb les classes que gestiona el docent, sense comptes personals.|Con menores de 14 años, solo con las clases que gestiona el docente, sin cuentas personales." },
      { id: 's7', k: 'activitat', t: 'Fes de laminador|Haz de laminador', timer: 8, punts: ['Calcula les capes: 3 + 2 mm.|Calcula las capas: 3 + 2 mm.', 'Dibuixa la capa 5 amb farciment.|Dibuja la capa 5 con relleno.', 'Dibuixa la capa 20.|Dibuja la capa 20.'], nota: 'Resposta: 25 capes; a la capa 20 només hi ha les lletres.|Respuesta: 25 capas; en la capa 20 solo están las letras.' },
      { id: 's8', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['La fitxa amb les inicials (Text de 2 mm a z = 3).|La ficha con las iniciales (Texto de 2 mm en z = 3).', 'La fitxa que flota: Alinea → A terra.|La ficha que flota: Alinea → Al suelo.', '⭐ El posagots massa gran.|⭐ El posavasos demasiado grande.'], nota: "Que provin el botó STL i comprovin on es descarrega.|Que prueben el botón STL y comprueben dónde se descarga." },
      { id: 's9', k: 'media', t: 'La fitxa de les inicials|La ficha de las iniciales', x: '32 mm · 3 mm de disc + 2 mm de lletres · 25 capes.|32 mm · 3 mm de disco + 2 mm de letras · 25 capas.', media: { k: 'model', model: FITXA }, nota: 'Una peça petita i ràpida per a la primera impressió.|Una pieza pequeña y rápida para la primera impresión.' },
      { id: 's10', k: 'media', t: 'Calen suports?|¿Hacen falta soportes?', x: 'La T dreta: sí. Estirada a la placa: no.|La T de pie: sí. Tumbada en la placa: no.', media: { k: 'model', model: TDRETA }, nota: "Pensar com es posa la peça a la placa estalvia suports.|Pensar cómo se pone la pieza en la placa ahorra soportes." },
      { id: 's11', k: 'repte', t: 'La teva fitxa per imprimir|Tu ficha para imprimir', punts: ['Personalitza-la.|Personalízala.', 'Passa la llista.|Pasa la lista.', "Descarrega'n l'STL i desa-la.|Descarga su STL y guárdala."], nota: 'Que la mantinguin petita: cap en 60 × 60 × 10 mm.|Que la mantengan pequeña: cabe en 60 × 60 × 10 mm.' },
      { id: 's12', k: 'concepte', t: 'Al laminador, pas a pas|En el laminador, paso a paso', x: "1 Obre l'STL · 2 Al mig de la placa, pla · 3 Capa 0,2 · farciment 15-20 % · sense suports · 4 Lamina · 5 Llegeix el temps i el filament · 6 Desa el fitxer per a la impressora.|1 Abre el STL · 2 En el centro de la placa, plano · 3 Capa 0,2 · relleno 15-20 % · sin soportes · 4 Lamina · 5 Lee el tiempo y el filamento · 6 Guarda el archivo para la impresora.", nota: "Feu-ho en directe amb una fitxa de la classe i apunteu el temps i el filament.|Hacedlo en directo con una ficha de la clase y apuntad el tiempo y el filamento." },
      { id: 's13', k: 'concepte', t: 'Seguretat|Seguridad', x: "El broquet arriba a uns 200 °C i la placa, a uns 60 °C. Sempre amb un adult i en un lloc ventilat.|La boquilla llega a unos 200 °C y la placa, a unos 60 °C. Siempre con un adulto y en un lugar ventilado.", nota: "Espereu que la placa es refredi per treure la peça.|Esperad a que la placa se enfríe para sacar la pieza." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['El camí: STL → laminador → impressora.|El camino: STL → laminador → impresora.', 'Capa 0,2 mm, farciment 15-20 %, suports si cal.|Capa 0,2 mm, relleno 15-20 %, soportes si hace falta.', "La llista abans d'imprimir.|La lista antes de imprimir."], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Tres coses que tries al laminador.|Tres cosas que eliges en el laminador.', 'Dues preguntes de la llista.|Dos preguntas de la lista.'], nota: 'Oral o escrit a la fitxa.|Oral o escrito en la ficha.' },
      { id: 's16', k: 'concepte', t: 'A casa|En casa', x: "Explica el camí d'un disseny fins a la impressora.|Explica el camino de un diseño hasta la impresora.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [
      { id: 'p1', t: 'Fitxa: preparo la impressió|Ficha: preparo la impresión', k: 'fitxa', intro: "La fitxa de les inicials: 32 mm de diàmetre, 3 mm de disc i 2 mm de lletres.|La ficha de las iniciales: 32 mm de diámetro, 3 mm de disco y 2 mm de letras.",
        items: [{ q: 'Quantes capes de 0,2 mm té?|¿Cuántas capas de 0,2 mm tiene?', sol: '5 mm × 5 = 25 capes.|5 mm × 5 = 25 capas.' }, { q: 'Al laminador tries: capa ____ mm · farciment ____ % · suports: sí / no|En el laminador eliges: capa ____ mm · relleno ____ % · soportes: sí / no', sol: '0,2 mm · 15-20 % · no (no té voladissos).|0,2 mm · 15-20 % · no (no tiene voladizos).' },
          { q: 'Segons el laminador, tardarà ____ minuts i gastarà ____ g de filament.|Según el laminador, tardará ____ minutos y gastará ____ g de filamento.', sol: "Resposta oberta: depèn de la impressora i del laminador.|Respuesta abierta: depende de la impresora y del laminador." },
          { q: "Marca la llista: placa · base plana · una sola peça · parets ≥ 1,2-2 mm · hi cap · voladissos ≤ 45°|Marca la lista: placa · base plana · una sola pieza · paredes ≥ 1,2-2 mm · cabe · voladizos ≤ 45°", sol: "La fitxa ho compleix tot.|La ficha lo cumple todo." }] },
      { id: 'p2', t: "Targetes: la llista abans d'imprimir|Tarjetas: la lista antes de imprimir", k: 'targetes', intro: "Retalleu-les i pengeu-les al costat de la impressora.|Recortadlas y colgadlas al lado de la impresora.",
        items: [{ t: 'Toca la placa?|¿Toca la placa?', n: 1 }, { t: 'Té una base plana?|¿Tiene una base plana?', n: 1 }, { t: 'És una sola peça?|¿Es una sola pieza?', n: 1 }, { t: 'Parets i traços de 1,2-2 mm o més?|¿Paredes y trazos de 1,2-2 mm o más?', n: 1 }, { t: 'Cap a la impressora?|¿Cabe en la impresora?', n: 1 }, { t: 'Voladissos de 45° o menys?|¿Voladizos de 45° o menos?', n: 1 }] }
    ]
  }
  };
})());
